(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).deut={"1":{"1":"Вот слова, с которыми Моисей обратился ко всему народу Израиля; это было за Иорданом, в пустыне, в Араве, близ Суфа, между Параном, Тофелом, Лаваном, Хацеротом и Ди – Захавом.","2":"(От Хорива до Кадеш – Барнеа, если идти по дороге, ведущей к Сеирским горам, одиннадцать дней пути.)","3":"На сороковой год, в первый день одиннадцатого месяца, Моисей возвестил сынам Израилевым все, что Господь повелел возвестить им.","4":"Это было после победы над Сихоном, аморейским царем, который правил в Хешбоне, и Огом, царем Башана, который правил в Аштароте и Эдрее.","5":"За Иорданом, в Моаве, Моисей стал подробно излагать Закон. Он сказал:","6":"«Господь, наш Бог, сказал нам на Хориве: „Хватит вам оставаться у этой горы.","7":"Отправляйтесь в путь, идите в горы, где живут амореи, и в земли их соседей – в Араву, в горы, в Шефелу, в Негев, на побережье, в страну ханаанеев, в Ливан – до великой реки, реки Евфрат.","8":"Всю эту землю Я отдаю вам! Идите и овладейте страной, которую Господь поклялся отдать вашим прародителям Аврааму, Исааку и Иакову – и их потомкам\".","9":"В ту пору я сказал вам: „Не под силу мне одному управлять вами.","10":"Господь, ваш Бог, сделал вас многочисленными, как звезды на небе.","11":"И пусть Он, Господь, Бог отцов ваших, сделает вас в тысячу раз многочисленнее, чем ныне, да благословит Он вас, как обещал!","12":"Но как же мне одному нести такое бремя, решать ваши тяжбы?","13":"Выберите из каждого племени мудрых, разумных и опытных людей, и я назначу их вашими начальниками\".","14":"Вы ответили: „Правильно ты говоришь!\"","15":"И я призвал к себе тех, кто стоял во главе племен, людей мудрых и опытных, и назначил их вашими начальниками – кого поставил над тысячей человек из его племени, кого над сотней, кого над полусотней, кого над десятком, кого старостой.","16":"В ту пору я велел вашим судьям: „Разбирайте тяжбы между вашими братьями; судите справедливо, будь то тяжбы между соплеменниками или тяжбы с чужаками, живущими у вас.","17":"Пусть суд ваш будет непредвзятым. Выслушивайте и сильного и слабого; не страшитесь людей, ибо суд – от Бога! А если дело будет слишком сложным для вас, передавайте его мне – я разберу\".","18":"В ту пору я дал вам все предписания о том, что вы должны делать.","19":"Мы двинулись от Хорива и прошли через пустыню, великую и страшную, – вы ее видели своими глазами! Направляясь, как повелел Господь, наш Бог, к горам, где живут амореи, мы дошли до Кадеш – Барнеа.","20":"Там я сказал вам: „Вы пришли к горам, где живут амореи, к горам, которые Господь, наш Бог, отдает нам.","21":"Смотрите, Господь, ваш Бог, отдает вам эту страну! Идите и овладейте ею – это обещал вам Господь, Бог отцов ваших. Не бойтесь, не страшитесь!\"","22":"Но вы, все вместе, пришли ко мне и сказали: „Надо послать вперед разведчиков, чтобы они исследовали страну и сказали нам, по какой дороге нам предстоит идти и к каким городам мы выйдем\".","23":"Это показалось мне разумным. Я выбрал двенадцать человек, по одному от каждого племени;","24":"они отправились в путь, поднялись в горы и дошли до долины Эшкол. Они осмотрели те места,","25":"набрали плодов земных, принесли их к нам и сказали: „Господь, наш Бог, дает нам хорошую землю!\"","26":"Но вы не захотели идти в поход. Вы ослушались Господа, вашего Бога!","27":"Сидя по своим шатрам, вы роптали: „Господь нас ненавидит – вот почему Он увел нас из Египта! Он отдаст нас в руки амореев, чтобы мы все погибли!","28":"Куда мы идем? Рассказы наших братьев и слушать страшно: они говорят, что там живут люди, которые больше и выше ростом, чем мы, говорят, что там большие укрепленные города, высотой до небес. Они говорят, что видели там анакимов!\"","29":"Я сказал вам: „Не пугайтесь, не бойтесь!","30":"Господь, ваш Бог, идет впереди, и Он Сам будет сражаться за вас. Так было в Египте, у вас на глазах!","31":"И в пустыне – вы сами это видели – Господь, ваш Бог, вас нес, будто человек, несущий своего сына; так было все время, пока вы шли сюда.","32":"И после всего этого вы не верите Господу, вашему Богу!","33":"А ведь Он шел впереди вас, выбирая вам места для стоянок, – ночью шел в виде огня, чтобы показывать вам правильную дорогу, а днем шел в виде облака\".","34":"Услышал Господь ваши слова и разгневался. Он поклялся: \"„Никто из этого негодного поколения не увидит прекрасную страну, которую Я поклялся отдать отцам вашим!","36":"Никто, кроме Калева, сына Иефунне: он – увидит. Он был верен Господу, и за это Я отдам ему и его потомкам землю, по которой он ступал\".","37":"И на меня разгневался Господь, из – за вас. Он сказал мне: „И ты не войдешь в эту страну!","38":"А Иисус Навин, твой раб, войдет! Вели ему быть твердым: ему предстоит сделать эти земли владением сынов Израилевых.","39":"Войдут в эту страну ваши дети – те самые, за которых вы боялись, что они попадут в плен, дети, которые сейчас еще не понимают, что хорошо и что плохо. Им Я отдам эту землю, они овладеют ею.","40":"А вы поворачивайте назад и идите в пустыню – по дороге, что ведет к морю Суф\".","41":"Тогда вы сказали мне: „Мы согрешили пред Господом. Но мы пойдем воевать, как повелел нам Господь, наш Бог!\" Вы взяли оружие и осмелились пойти в горы.","42":"Господь велел мне передать вам: „Не ходите. Не начинайте войну, ведь Я не с вами. А не то враги разобьют вас!\"","43":"Я передал это вам, но вы не вняли. Вы ослушались Господа и дерзнули подняться в горы.","44":"Вас встретили амореи, обитатели этих гор. Они устремились за вами, как пчелиный рой! Они гнали вас по Сеиру, до самой Хормы !","45":"Вернувшись, вы плакали пред Господом, но Господь не слушал вас, не внимал вам.","46":"Вы пробыли в Кадеше долгое время."},"2":{"1":"Мы повернули назад и пошли в пустыню, по дороге, что ведет к морю Суф; так повелел мне Господь. Мы долго шли, огибая Сеирские горы.","2":"Потом Господь сказал мне:","3":"„Хватит вам идти вокруг этих гор. Поворачивайте на север.","4":"И передай народу: вы пойдете по земле ваших братьев, потомков Исава, обитателей Сеира. Они боятся вас. Смотрите же,","5":"не начинайте войну с ними! Ни пяди их земли Я не отдам вам, потому что Сеирские горы Я дал во владение Исаву.","6":"И еду, которую вы будете есть, и воду, которую будете пить, покупайте у них за серебро.","7":"Господь, ваш Бог, благословляет вас во всех ваших делах! Ведомо Ему, как вы идете по этой великой пустыне. Уже сорок лет Господь, ваш Бог, с вами – и вы ни в чем не испытываете нужды\".","8":"Мы ушли прочь от страны наших братьев, потомков Исава, обитателей Сеира, от дороги, что идет по Араве, от Элата и Эцион – Гевера – и направились в Моавскую пустыню.","9":"Господь сказал мне: „Не нападайте на моавитян, не начинайте войну с ними. Из их земель Я ничего вам не отдам, потому что Я дал Ар во владение потомкам Лота\".","10":"(Прежде там жили эмеи, народ большой, многочисленный – и рослый, как анакимы.","11":"Их, как и анакимов, причисляют к рефаимам; моавитяне называют их эмеями.","12":"А в Сеире прежде жили хорреи, но потомки Исава завладели их землей, истребили их и поселились там – сделали то же самое, что сделали сыны Израилевы в той стране, которую Господь отдал им во владение.)","13":"„Вперед! – сказал Господь. – Переходите ущелье Зеред!\" И мы перешли ущелье Зеред.","14":"Тридцать восемь лет шли мы от Кадеш – Барнеа – и вот перешли через Зеред. В нашем стане уже не было никого из воинов прежнего поколения – как и поклялся им Господь.","15":"Рука Господа настигала их в нашем стане одного за другим, и наконец никого из них в живых не осталось.","16":"Когда эти воины умерли, все до одного,","17":"Господь сказал мне:","18":"„Вы идете через Ар, по моавской земле,","19":"и скоро достигнете страны аммонитян. Не нападайте на них, не начинайте войну с ними. Из их земель Я ничего вам не отдам, потому что Я дал эти земли во владение потомкам Лота\".","20":"(Эту страну тоже причисляют к землям рефаимов: прежде в ней жили рефаимы, которых аммонитяне называют замзуммеями.","21":"Это был народ большой, многочисленный – и рослый, как анакимы. Но Господь истребил их – аммонитяне овладели их землей и поселились там.","22":"Господь сделал для аммонитян то же, что сделал Он для потомков Исава, живущих в Сеире. Ведь Он истребил хорреев – потомки Исава овладели их землей и живут там до сих пор.","23":"А аввеев, что жили в селениях вокруг Газы, истребили кафторяне – народ, прибывший с Кафтора, – и тоже поселились на их земле.)","24":"„Вперед! – сказал Господь. – Переходите ущелье Арнон! Смотрите, Я отдаю в ваши руки Сихона – аморея, царя хешбонского, и его страну. Начинайте завоевания! Воюйте!","25":"С этого дня Я буду вселять во все народы, какие есть под небом, страх и ужас перед вами. Услышав про вас, они будут дрожать и трепетать!\"","26":"Из пустыни Кедемот я отправил послов к Сихону, царю хешбонскому, предлагая ему мир. Я велел передать ему:","27":"„Позволь мне пройти по твоей земле. Я пойду по дороге, не сверну ни вправо, ни влево.","28":"И еду, что мы будем есть, и воду, что мы будем пить, ты будешь продавать нам за серебро. Только позволь пройти по твоей земле –","29":"как позволили потомки Исава, живущие в Сеире, и моавитяне, живущие в Аре, – и мы уйдем за Иордан, в ту страну, которую дает нам Господь, наш Бог\".","30":"Но Сихон, царь хешбонский, не захотел пропустить нас. Господь, ваш Бог, сделал его дух упрямым, а сердце непреклонным, чтобы отдать Сихона в ваши руки – что и свершилось.","31":"Господь сказал мне: „Смотри, сперва Я отдам тебе Сихона и его страну! Начни с завоевания этой страны\".","32":"Сихон со всем своим войском вышел нам навстречу и вступил с нами в бой у Яхаца.","33":"Господь, наш Бог, отдал его в наши руки: мы убили его и его сыновей, перебили все его войско.","34":"В ту пору мы овладели всеми его городами и предали их заклятью – уничтожили. В этих городах мы истребили и мужчин, и женщин, и детей, всех до последнего.","35":"Только скот и захваченную в городах добычу мы оставили себе.","36":"От Ароэра, что над Арнонской долиной, и селения, что в долине, ни одна крепость, до самого Галаада, не смогла дать нам отпор. Господь, наш Бог, отдал нам все!","37":"Но на страну аммонитян вы не нападали – ни на долину реки Яббок, ни на горные селения. Так велел Господь, ваш Бог."},"3":{"1":"Повернув, мы пошли по дороге, ведущей в Башан. Ог, царь башанский, вышел нам навстречу со всем своим войском и вступил с нами в бой у Эдреи.","2":"Господь сказал мне: „Не бойся. Я отдаю в твои руки и его самого, и все его войско, и его страну. Ты поступишь с ним так же, как с Сихоном, аморейским царем, правившим в Хешбоне\".","3":"Господь, наш Бог, отдал в наши руки и Ога, царя башанского, со всем его войском: мы перебили их, всех до последнего!","4":"В ту пору мы овладели всеми его городами. Мы захватили все города до одного – это шестьдесят городов, вся область Аргов, башанское царство Ога.","5":"Все это были укрепленные города с высокими стенами и воротами на запоре (а сверх того – множество неогражденных селений).","6":"Мы предали их заклятью и уничтожили – поступили так же, как с Сихоном, царем хешбонским. В этих городах мы истребили и мужчин, и женщин, и детей.","7":"А весь скот и захваченную в городах добычу мы оставили себе.","8":"Итак, в ту пору мы завоевали земли двух аморейских царей, правивших за Иорданом, – земли от Арнонской долины до горы Хермон","9":"(сидоняне называют ее Сирион, а амореи – Сенир) –","10":"все селения Плоскогорья, весь Галаад и весь Башан, вплоть до Салхи и Эдреи, городов башанского царства Ога.","11":"(Ог, царь башанский, был последним из рефаимов. А ложе его – железное. Сейчас оно в Равве Аммонской; оно – девяти локтей в длину и четырех в ширину, в обычных локтях.)","12":"Земли, которыми мы овладели в ту пору, начиная от Ароэра, что над Арнонской долиной, и включая половину Галаадского нагорья с его селениями, я отдал племенам Рувима и Гада.","13":"Остальной Галаад, а также весь Башан, царство Ога, я отдал половине племени Манассии. (Всю область Аргбов – весь Башан – прежде называли землей рефаимов.","14":"Но Яир, сын Манассии, овладел всей областью Аргов, вплоть до границ с гешурцами и маахейцами, и назвал ее своим именем, так что и по сей день Башан называют Яировыми Деревнями.)","15":"Махиру я отдал Галаад.","16":"Племенам же Рувима и Гада я отдал землю от Галаада до Арнонской долины, с границей по дну долины, и до реки Яббок, за которой живут аммонитяне.","17":"Кроме того, я отдал им Араву, с границей по Иордану, от Киннерета до Аравского (Мертвого) моря – и до склонов горы Фасга на востоке.","18":"В ту пору я дал этим племенам такой наказ: „Господь, ваш Бог, отдал вам во владение эту землю. Но вы, воины, должны идти на бой впереди всех сынов Израилевых!","19":"А ваши жены, дети и скот – я знаю, как много у вас скота! – пусть остаются в селениях, которые я дал вам.","20":"Когда Господь дарует братьям вашим мирную жизнь, как даровал ее вам, – когда они овладеют страной на том берегу Иордана, которую отдает им Господь, ваш Бог, – тогда вы вернетесь в свои наделы, которые я дал вам\".","21":"В ту пору я сказал Иисусу: „Ты своими глазами видел, что сделал Господь, ваш Бог, с этими двумя царями. То же самое Господь сделает со всеми царствами, по которым ты будешь идти.","22":"Не бойтесь их: Господь, ваш Бог, Сам воюет за вас!\"","23":"В ту пору я взмолился к Господу:","24":"„Владыка Господь! Ты начал являть мне, рабу Своему, Твое величие и силу руки Твоей! Разве есть другой бог, на небе или на земле, которому были бы по силам такие дела и свершения?","25":"Позволь же мне перейти реку и увидеть прекрасную страну за Иорданом – и эти прекрасные горы, и Ливан!\"","26":"Но Господь гневался на меня из – за вас и не стал меня слушать. Он сказал: „Довольно! Больше не проси Меня об этом.","27":"Взойди на гору Фасга и погляди на запад, на север, на юг и на восток, погляди своими глазами, ибо не суждено тебе перейти Иордан.","28":"Отдай распоряжения Иисусу, вели ему быть твердым и стойким. Он пойдет во главе этих людей – и сделает их владением страну, которую тебе дано лишь увидеть\".","29":"Мы остановились в долине близ Бет – Пеора."},"4":{"1":"Слушай же, Израиль, предписания и законы, которым я буду учить тебя! Тогда вы будете живы и, придя в страну, которую Господь, Бог отцов ваших, отдает вам, овладеете этой страной.","2":"Ничего не добавляйте к моим словам, ничего не убавляйте. Исполняйте повеления Господа, вашего Бога, которые я вам возвещаю.","3":"Вы сами видели, что сделал Господь в Баал – Пеоре! Господь, ваш Бог, истребил тех из вас, кто пошел за Пеорским Ваалом.","4":"А вы, оставшиеся верными Господу, вашему Богу, – вы все живы и по сей день.","5":"Вот, я учу вас предписаниям и законам, как велел мне Господь, мой Бог. Вы должны исполнять их в той стране, в которую придете и которой овладеете.","6":"Строго соблюдайте и исполняйте их – и тогда все народы увидят вашу мудрость и разум. Услышав обо всех этих предписаниях, они скажут: „Как мудр и разумен этот великий народ!\"","7":"Есть ли еще такой великий народ – народ, чьи боги были бы так близки к нему, как близок к нам Господь, наш Бог, когда мы призываем Его?","8":"Есть ли еще такой великий народ – народ, чьи правила и законы были бы так справедливы, как этот Закон, который я даю вам ныне?","9":"Смотри же, берегись, не забывай того, что ты видел своими глазами; пусть увиденное пребудет в памяти твоей, пока ты жив! Рассказывай и детям, и внукам.","10":"В тот день вы стояли пред Господом, вашим Богом, у Хорива, ибо Господь велел мне: „Собери ко Мне народ, и Я возвещу им Мои повеления. Пусть они научатся всю свою жизнь на земле бояться и чтить Меня, и детей своих пусть научат\".","11":"И вот вы подошли и встали под горой, а гора пылала огнем, доходившим до самого неба. Был мрак – облако, густая тьма.","12":"Господь говорил с вами из огня, и вы слышали слова, но никакого образа не видели – лишь голос звучал.","13":"Господь возвестил вам условия договора с Ним, которые вы должны выполнять, – Десять Заповедей. Он написал их на двух каменных табличках.","14":"В ту пору Господь велел мне научить вас предписаниям и законам, чтобы вы соблюдали их в стране, в которую идете и которой овладеете.","15":"Когда Господь говорил с вами из огня на Хориве, вы не видели никакого образа. Остерегайтесь же","16":"сотворить зло – сделать себе изваяние, какое-либо изображение, в виде мужчины или женщины,","17":"в виде животного, обитающего на земле, или птицы, летающей в небесах,","18":"в виде живности земной или рыбы, плавающей в воде, ниже земли.","19":"Глядя на небо, видя солнце, луну и звезды, все небесное воинство, не поддавайся соблазну – не поклоняйся им, не служи им! Господь, ваш Бог, предназначил их для всех прочих народов под небесами.","20":"А вас Господь забрал, вывел из этой плавильной печи, из Египта, чтобы вы стали Его собственным народом – что и свершилось.","21":"Господь разгневался на меня из – за вас и поклялся, что я не перейду Иордан и не войду в ту прекрасную страну, которую Господь, ваш Бог, отдает вам во владение.","22":"Я умру здесь, так и не перейдя Иордан. А вы его перейдете и овладеете той прекрасной страной!","23":"Но смотрите, не забывайте договор, который заключил с вами Господь, ваш Бог: не делайте себе изваяний, не делайте никаких изображений. Это запретил вам Господь, ваш Бог.","24":"Ибо Господь, твой Бог, – это огонь испепеляющий! Он – Бог ревнивый!","25":"Когда у вас родятся дети и внуки, когда вы уже долго проживете в той стране, вы сотворите зло – станете делать изваяния, различные изображения. Творя дела, ненавистные Господу, вашему Богу, вы прогневаете Его.","26":"Я беру ныне в свидетели небо и землю, что после этого вы быстро исчезнете из той страны, которой вы сейчас овладеете, перейдя Иордан! Тогда вам уже недолго останется жить там: вы будете истреблены.","27":"Господь рассеет вас среди народов. Лишь немногие из вас уцелеют – и будут жить среди народов, к которым вас отправит Господь.","28":"Там вы будете служить богам, которые созданы руками человека, – деревяшкам и камням – богам, которые не видят, не слышат, не едят и не чувствуют запахов.","29":"Там вы станете искать Господа, вашего Бога, – и найдете, если устремитесь к Нему всем сердцем и всей душою.","30":"Когда будет вам тяжко, когда, в далеком будущем, постигнет вас все это – тогда вы вернетесь к Господу, вашему Богу, и станете Его слушаться.","31":"Ведь Господь, ваш Бог, – Бог милосердный: Он не оставит вас и не погубит, Он не забудет тот договор, что заключил Он с отцами вашими, дав им клятву.","32":"Расспроси о прежних временах, о том, что было до тебя, начиная с того дня, когда Бог сотворил на земле человека: было ли где-нибудь, от одного края неба до другого, нечто столь же великое? Слышал ли кто о чем-то подобном?","33":"Случалось ли, чтобы какой-нибудь народ, подобно вам, слышал голос бога, говорящего из огня, и остался жив?","34":"Пробовал ли какой-либо бог прийти и взять себе народ, живущий среди другого народа, – посылая тяжкие испытания, и знамения, и чудеса, и войну, совершая рукой Своей могучей, десницей простертой, великие и страшные деяния? Все это сделал ради вас Господь, ваш Бог, в Египте, у вас на глазах.","35":"Вам дано было все это увидеть, чтобы вы поняли, что Господь – это Бог; нет бога, кроме Него.","36":"Он воззвал к вам с неба, наставляя вас. Он показал вам Свой великий огонь на земле, и вы слышали, как Он говорил с вами из огня.","37":"Господь возлюбил отцов ваших – и потому избрал вас, их потомков. Он Сам вывел вас из Египта силою Своей великой,","38":"чтобы отдать вам землю народов, более многочисленных и сильных, чем вы, – привести вас на их землю и отдать ее вам во владение (что и свершилось).","39":"Познайте же ныне и запомните, что Господь – это Бог на небе вверху и на земле внизу, и другого нет.","40":"Исполняйте Его предписания и повеления, которые я возвещаю вам ныне, и хорошо будет вам и потомкам вашим, и долго будете вы жить в той стране, которую Господь, ваш Бог, отдает вам – навсегда».","41":"В то время Моисей выделил три города на восток от Иордана,","42":"чтобы всякий, кто неумышленно убьет ближнего, с которым прежде не враждовал, мог бежать в один из этих городов и тем спасти свою жизнь.","43":"Вот эти города: Бецер в пустыне, на Плоскогорье, в наделе Рувима; Рамот в Галааде, в наделе Гада; Голан в Башане, в наделе Манассии.","44":"Вот Закон, который Моисей дал сынам Израилевым.","45":"Это наказы, предписания и законы, которые Моисей возвестил сынам Израилевым после ухода из Египта –","46":"за Иорданом, в долине близ Бет – Пеора, на земле Сихона, аморейского царя, правившего в Хешбоне. (Моисей и сыны Израилевы, уйдя из Египта, победили Сихона","47":"и захватили его страну, вместе со страной Ога, царя башанского. Земли этих двух аморейских царей простирались восточнее Иордана,","48":"от Ароэра, что над Арнонской долиной, до горы Сирион, она же Хермон,","49":"и включали всю восточную, заиорданскую Араву, вплоть до Аравского моря и до склонов горы Фасга.)"},"5":{"1":"Моисей созвал всех сынов Израилевых и сказал: «Слушай, Израиль, предписания и законы, которые я возвещаю вам ныне! Заучите их, строго соблюдайте и исполняйте их.","2":"Господь, наш Бог, заключил с нами договор на Хориве.","3":"Не с нашими отцами Господь заключил этот договор, а с нами – со всеми нами, с теми, кто жив и стоит здесь ныне.","4":"Господь говорил с вами лицом к лицу – говорил на горе, из огня.","5":"Я стоял в ту пору между Господом и вами, чтобы передавать вам Его слова, потому что вы боялись огня и не поднимались на гору. Он сказал:","6":"„Я Господь, твой Бог, который вывел тебя из Египта, из неволи.","7":"Пусть у тебя не будет никаких богов, кроме Меня.","8":"Не делай изваяний – никаких изображений того, что вверху на небе, того, что внизу на земле, или того, что в воде, ниже земли.","9":"Не поклоняйся им и не служи им, ибо Я, Господь, твой Бог, – Бог ревнивый. За грехи отцов, отвергнувших Меня, Я караю их детей, внуков и правнуков.","10":"А потомкам тех, кто Меня любит и исполняет Мои повеления, Я и в тысячном поколении воздаю добром.","11":"Не произноси попусту имя Господа, твоего Бога. Господь не оставит безнаказанным того, кто так делает.","12":"Соблюдай субботу – священный день, как повелел тебе Господь, твой Бог.","13":"Шесть дней работай, занимайся делами,","14":"а седьмой день – суббота: он принадлежит Господу, твоему Богу. Работать в этот день нельзя никому – ни тебе, ни сыну твоему, ни дочери, ни рабу твоему, ни рабыне, ни быку твоему или ослу – никакой скотине, ни переселенцу, что живет в твоем городе. Пусть твой раб и твоя рабыня отдохнут, как и ты.","15":"Помни, что ты сам был рабом в Египте, а Господь, твой Бог, вывел тебя оттуда рукой Своей могучей, десницей простертой. Поэтому Господь, твой Бог, повелел тебе соблюдать субботу.","16":"Чти отца и мать, как повелел тебе Господь, твой Бог, чтобы долгой была твоя жизнь и чтобы было тебе хорошо на той земле, которую Господь, твой Бог, дарует тебе.","17":"Не убивай.","18":"Не прелюбодействуй.","19":"Не воруй.","20":"Не давай ложных показаний против ближнего.","21":"Не желай отнять чужую жену. Не пожелай чужого дома и поля, чужих рабов и рабынь, чужих быков и ослов – ничего чужого\".","22":"Господь сказал это всей вашей общине. Он говорил на горе, из огня, облака и густой тьмы, громким голосом. К этим словам Он ничего не добавил. Он написал их на двух каменных табличках и отдал таблички мне.","23":"Вы внимали голосу, звучавшему из тьмы, а гора пылала огнем. И подошли ко мне вы, вожди племен и старейшины.","24":"Вы сказали: „Господь, наш Бог, показал нам Свою славу и величие. Мы слышали Его голос, звучавший из огня. Сегодня мы узнали, что человек может остаться в живых даже тогда, когда с ним говорит Бог.","25":"И зачем же нам умирать – ведь это великое пламя готово нас поглотить! Если мы снова услышим голос Господа, нашего Бога, то умрем!","26":"Бывало ли такое, чтобы человек слышал, подобно нам, как живой Бог говорит с ним из пламени, и остался бы жив?","27":"Ты иди и слушай, что скажет Господь, наш Бог. Потом ты передашь нам все, что Господь, наш Бог, возвестит тебе. А мы будем слушать и исполнять\".","28":"Господь услышал ваши слова и сказал мне: „Я слышал, что говорили эти люди, слышал все, что они тебе сказали. Правильно они говорят.","29":"О, если бы они и впрямь были всем сердцем расположены всегда бояться Меня и выполнять все Мои повеления, чтобы им и их потомкам было хорошо вовеки!","30":"Иди и вели им вернуться в шатры.","31":"Ты же останешься здесь, со Мной. Я возвещу тебе все повеления, предписания и законы. Ты научишь их, и они будут выполнять все это в стране, которую Я отдаю им во владение\".","32":"Строго соблюдайте и исполняйте то, что повелел вам Господь, ваш Бог, не уклоняйтесь ни вправо, ни влево!","33":"Всегда ходите теми путями, которые заповедал вам Господь, ваш Бог. И будете вы живы, и будет вам хорошо, и долго будете вы жить в той стране, которой овладеете."},"6":{"1":"Вот повеления, предписания и законы, которым Господь, ваш Бог, велел научить вас, – вы должны исполнять их в той стране, в которую идете и которой овладеете.","2":"И будете вы во все дни жизни вашей бояться и чтить Господа, вашего Бога, и соблюдать все Его предписания и повеления, которые я вам возвещаю, и так же будут поступать ваши дети и внуки, и тогда вы будете жить долго.","3":"Слушай же, Израиль! Строго соблюдайте и исполняйте все это! Тогда вам будет хорошо и вы станете многочисленны на земле, источающей молоко и мед, – как обещал вам Господь, Бог отцов ваших.","4":"Слушай, Израиль! Господь, наш Бог, – единственный Господь!","5":"Люби Господа, твоего Бога, всем сердцем, всей душой, всеми силами.","6":"Пусть повеления, которые я даю тебе ныне, всегда будут у тебя в памяти.","7":"Пересказывай их своим детям, повторяй их постоянно – дома ты или в пути, ложишься или встаешь.","8":"Повяжи их на руку как знак, пусть они будут повязкой у тебя на лбу.","9":"Напиши их на дверных косяках твоего дома и на городских воротах.","10":"Господь, твой Бог, приведет тебя в страну, которую Он обещал отдать тебе, как поклялся Он в этом твоим прародителям Аврааму, Исааку и Иакову. Там – большие и процветающие города, не тобой возведенные,","11":"дома, полные всякого добра, не тобой собранного, колодцы, не тобою высеченные, виноградники и оливковые рощи, не тобою посаженные. Там ты будешь есть досыта!","12":"Смотри же, не забывай Господа – Того, кто вывел тебя из Египта, из неволи.","13":"Бойся Господа, твоего Бога, служи Ему, клянись Его именем.","14":"Не следуйте за другими богами, богами народов, живущих вокруг вас,","15":"ведь Господь, ваш Бог, пребывающий среди вас, – Бог ревнивый: Он разгневается и сметет вас с лица земли!","16":"Не испытывайте Господа, вашего Бога, как вы испытывали Его в Массе.","17":"Исполняйте повеления Господа, вашего Бога, наказы и предписания, которые Он вам дал.","18":"Делайте то, что правильно и хорошо в Его глазах. Тогда вам будет хорошо: вы придете и овладеете прекрасной страной, которую Господь поклялся отдать отцам вашим.","19":"Господь прогонит из нее всех ваших врагов. Так сказал Господь.","20":"Когда в будущем спросит у тебя сын: „Что означают эти наказы, предписания и законы, которые дал вам Господь, наш Бог?\" –","21":"отвечай ему так: „Мы были рабами у фараона в Египте, и Господь сильной рукой вывел нас из Египта.","22":"У нас на глазах Господь явил великие чудеса и знамения, гибельные для Египта, для фараона и всего его дома.","23":"А нас Он вывел из Египта, чтобы привести нас в страну и даровать ее нам, как поклялся Он в этом отцам нашим.","24":"Господь велел нам выполнять все эти предписания – бояться и чтить Господа, нашего Бога, чтобы нам всегда было хорошо, чтобы мы были живы (так оно и есть – поныне).","25":"Праведность наша – в том, чтобы строго соблюдать и исполнять пред Господом, нашим Богом, все эти повеления, как Он и заповедал нам\"."},"7":{"1":"Когда Господь, ваш Бог, приведет вас в страну, овладеть которой вы идете, и изгонит из нее множество народов: хеттов, гиргашеев, амореев, ханаанеев, периззеев, хиввеев и евусеев – семь народов, более многочисленных и сильных, чем вы, –","2":"когда Господь, ваш Бог, отдаст их в ваши руки и вы победите их, то предайте их заклятию – уничтожьте! Не заключайте с ними договоров и не давайте им пощады.","3":"Не вступайте с ними в родство, не выдавайте своих дочерей замуж за их сыновей и не берите их дочерей в жены своим сыновьям.","4":"Иначе они отвратят от Меня ваших сыновей и те будут служить другим богам! Тогда Господь разгневается на вас и немедленно вас уничтожит.","5":"Поступите так: их жертвенники – разрушьте, их священные камни – разбейте, дерева Ашеры – срубите, изваяния – сожгите!","6":"Ведь вы – святой народ у Господа, вашего Бога; Господь, ваш Бог, избрал вас из всех народов земли, чтобы вы были Его драгоценным достоянием.","7":"Господь возлюбил вас и избрал не потому, что вы многочисленнее всех других народов. Нет, вы – самый малый из народов!","8":"Но Господь любит вас и хранит верность клятве, которую дал отцам вашим, – вот почему Он увел вас сильной рукою, освободил из неволи, из – под власти фараона, царя египетского.","9":"Знай же, что Господь, твой Бог, – поистине Бог, Бог надежный; Он верен, до тысячного поколения, договору с теми, кто Его любит и исполняет повеления Его.","10":"А всех, кто Его отвергает, Он покарает и уничтожит – без промедления покарает их всех!","11":"Поэтому исполняй повеления, предписания и законы, которые я возвещаю тебе ныне.","12":"Если вы будете повиноваться этим законам, если будете строго соблюдать и исполнять их, то и Господь, ваш Бог, будет верен тому договору, что заключил Он с отцами вашими.","13":"Он будет любить вас, Он благословит вас и сделает многочисленным народом, Он благословит ваше потомство и урожай вашей земли, ваше зерно, вино и оливковое масло, приплод коров, приплод овец и коз на той земле, которую Он обещал отдать вам, поклявшись в этом отцам вашим.","14":"Вы будете благословенны, как ни один другой народ! Среди вас не будет бесплодных мужчин или женщин, и скот ваш не будет бесплодным.","15":"Господь избавит вас от всех недугов. Он не пошлет на вас губительные египетские болезни (вы о них помните!), а пошлет их на ваших врагов.","16":"Вы истребите все народы, которые Господь, ваш Бог, отдаст вам в руки; вы не должны жалеть их, не должны служить их богам – это станет для вас западней.","17":"Вы, возможно, подумаете: „Эти народы многочисленнее нас. Как же мы отберем у них землю?\"","18":"Но не бойтесь их! Вспомните, что сделал Господь, ваш Бог, с фараоном и со всем Египтом,","19":"вспомните великие и тяжкие испытания, которые вы видели своими глазами, и знамения, и чудеса, вспомните, как Господь, ваш Бог, вывел вас из Египта рукой Своей могучей, десницей простертой. Господь, ваш Бог, поступит так и со всеми народами, которых вы боитесь ныне.","20":"А еще Он пошлет на них осиный рой, и погибнут даже те, кто уцелел и спрятался от вас.","21":"Не страшитесь, ведь среди вас пребывает Господь, ваш Бог, Бог великий и грозный!","22":"(Но Господь, ваш Бог, будет изгонять эти народы постепенно. Вам не дано будет уничтожить их быстро – иначе там слишком размножились бы дикие звери.)","23":"Господь, ваш Бог, дарует вам победу над этими народами, посеет среди них великое смятение, и они будут истреблены.","24":"Он отдаст их царей в ваши руки, и вы даже имени их не оставите под небесами. Никто не выстоит перед вами, и вы истребите их всех.","25":"Сожгите изваяния их богов. Не бери себе, соблазнившись, серебра и золота, которыми покрыты эти изваяния, а не то попадешь в западню – ведь для Господа, твоего Бога, это мерзость.","26":"Не вноси мерзость в свой дом, иначе и сам подпадешь под заклятье вместе с ней. Пусть такая вещь будет для тебя отвратительной и мерзкой – это заклятое."},"8":{"1":"Строго соблюдайте и исполняйте все повеления, которые я возвещаю вам ныне. Тогда вы будете живы и станете многочисленны; вы придете и овладеете страной, которую Господь поклялся отдать отцам вашим.","2":"Вспомните, как Господь, ваш Бог, вел вас по пустыне все эти сорок лет, чтобы смирить вас, и испытать, и узнать вас: будете вы выполнять Его повеления или нет.","3":"Он смирял вас, заставлял голодать, кормил вас манной, о которой ни вы, ни ваши отцы и не ведали. Он хотел показать вам, что не одним лишь хлебом живет человек. Человек живет всем тем, что исходит из уст Господа!","4":"Все эти сорок лет одежда твоя не изнашивалась, ноги твои не опухали.","5":"Пойми же, что Господь, твой Бог, учит тебя, как отец учит сына!","6":"Исполняй повеления Господа, твоего Бога, ходи путями Его, бойся Его и чти.","7":"Господь, твой Бог, приведет тебя в прекрасную страну, в страну, где текут реки, где в долинах и средь гор пробиваются родники и подземные воды,","8":"в страну пшеницы и ячменя, виноградников, смоковниц и гранатов, в страну оливковых деревьев и меда.","9":"В этой стране ты не будешь жить впроголодь, ни в чем не испытаешь нужды; в ее камнях есть железо, из гор ее ты сможешь добывать медь.","10":"Насытившись, благословляй Господа, твоего Бога, за прекрасную страну, которую Он отдал тебе.","11":"Смотри же, не забывай Господа, твоего Бога, исполняй все Его повеления, законы и предписания, которые я возвещаю тебе ныне.","12":"Когда ты станешь есть досыта, построишь хорошие дома и будешь жить в них,","13":"когда у тебя будет много крупного и мелкого скота, много серебра и золота, много всякого добра,","14":"то не возгордись и не забудь Господа, твоего Бога. Он вывел тебя из Египта, из неволи,","15":"вел тебя по великой и страшной пустыне, меж ядовитых змей и скорпионов, по сухой и безводной земле. Ради тебя Он заставил воду течь из скалы;","16":"Он кормил тебя в пустыне манной, о которой твои отцы и не ведали. Он смирял и испытывал тебя, чтобы потом тебе было хорошо.","17":"Не думай, что ты сам, своими силами приобрел все это богатство!","18":"Помни Господа, твоего Бога. Это Он помогает тебе обрести богатство – Он и по сей день соблюдает договор, заключенный с твоими отцами.","19":"Если же вы забудете Господа, вашего Бога, и пойдете за другими богами, будете служить и поклоняться им, то вы непременно погибнете – предупреждаю вас об этом ныне!","20":"Если не будете слушаться Господа, вашего Бога, то вы погибнете, как те народы, которые Господь уничтожает, чтобы отдать вам их землю."},"9":{"1":"Слушай, Израиль! Ныне вы переходите Иордан, чтобы овладеть землей народов, которые многочисленнее и сильнее вас, большими укрепленными городами, высотой до небес,","2":"землей большого и рослого народа, анакимов, – вы о них знаете, ведь вы слыхали, как люди говорят: „Кто выстоит перед анакимами?!\"","3":"Осознайте же ныне, что это Господь, ваш Бог, идет впереди вас, как огонь испепеляющий. Это Он уничтожит их, дарует вам победу над ними, – и вы захватите их землю, быстро истребите их, как и обещал вам Господь.","4":"Когда Господь, ваш Бог, прогонит их, не говорите себе: „За нашу праведность Господь привел нас сюда, чтобы мы овладели этой страной\". Нет, из – за злодеяний этих народов Господь отдает вам их землю!","5":"Вы придете и овладеете их страной не потому, что вы правы и праведны. Господь, ваш Бог, отдает вам их землю потому, что эти народы виновны, и для того, чтобы исполнить клятву, которую Он дал вашим прародителям Аврааму, Исааку и Иакову.","6":"Знайте же, что Господь, ваш Бог, отдает вам во владение ту прекрасную страну не за праведность вашу (нет, вы народ упрямый!).","7":"Помните и не забывайте, как вы гневили Господа, вашего Бога, в пустыне. Со дня вашего ухода из Египта до прихода сюда вы все время бунтовали против Господа.","8":"Вы прогневали Господа у Хорива, так что Он в ярости хотел вас уничтожить.","9":"…Поднявшись на гору, чтобы взять каменные таблички, таблички того договора, что заключил с вами Господь, я провел на горе сорок дней и сорок ночей, не ел и не пил.","10":"И Господь дал мне две каменные таблички; на них было начертано перстом Божьим все то, что Господь сказал вам из огня, на горе, в день собрания всей общины.","11":"Прошло сорок дней и сорок ночей – Господь дал мне две каменные таблички, таблички договора.","12":"И сказал мне Господь: „Поторопись, спускайся! Негодным стал твой народ, выведенный тобою из Египта. Как быстро они свернули с того пути, на который Я их наставил! Они сделали себе литую статую\".","13":"Господь сказал мне: „Я вижу, что это народ упрямый!","14":"Не удерживай Меня – Я уничтожу их, сотру имя их под небесами. А от тебя Я произведу народ, который будет сильнее и многочисленнее\".","15":"Я повернулся и стал спускаться с горы. Гора пылала огнем; в руках у меня были две таблички договора.","16":"И я увидел, что вы и вправду согрешили пред Господом, вашим Богом, – сделали себе литую статую тельца. Быстро вы свернули с того пути, на который вас наставил Господь!","17":"Тогда я бросил обе таблички наземь – разбил их у вас на глазах.","18":"Потом я снова простерся пред Господом – опять не ел и не пил сорок дней и сорок ночей – из – за греха, который вы совершили, сотворив дело, ненавистное Господу, и прогневав Его.","19":"Страшно мне было, ведь Господь в гневе и ярости собирался уничтожить вас. Но Он послушал меня и на этот раз.","20":"Господь сильно гневался на Аарбна и хотел уничтожить его, но я тогда же просил и за Аарона.","21":"А ваш грех, тельца, которого вы сделали, я сжег, измельчил, растолок, растер в пыль – и бросил эту пыль в ручей, текущий с горы.","22":"Вы гневили Господа и в Тавере, и в Массе, и в Киврот – ха – Тааве .","23":"Когда Господь велел вам выступить в поход из Кадеш – Барнеа – когда Он сказал: „Идите и овладейте страной, которую Я вам отдаю!\" – вы ослушались Господа, вашего Бога, не поверили и не вняли Ему.","24":"Все то время, что я вас знаю, вы не слушались Господа!","25":"…Я пал тогда ниц пред Господом и лежал, простершись пред Ним, сорок дней и сорок ночей – ведь Он сказал, что хочет вас уничтожить.","26":"Я умолял Господа: „Владыка Господь, не губи Свой народ, Свое достояние! Ты освободил их Своей великой властью, рукою сильной вывел их из Египта.","27":"Вспомни же Своих рабов Авраама, Исаака и Иакова, не смотри на упрямство этого народа, на его вину и грехи.","28":"А иначе в той стране, откуда Ты нас вывел, скажут:, Господь не мог привести их в землю, которую обещал им. Он ненавидел их. И Он увел их в пустыню, чтобы там погубить.","29":"Но ведь они – Твой народ и Твое достояние, Ты вывел их Своей великой силой, рукой простертой!\""},"10":{"1":"В ту пору Господь сказал мне: „Вытеши из камня две таблички, подобные прежним, и поднимись на гору, ко Мне. И еще сделай деревянный ковчег.","2":"Я напишу на табличках те же слова, что были на прежних табличках, разбитых тобою, и ты положишь их в ковчег\".","3":"Я сделал ковчег из акации, вытесал из камня две таблички, подобные прежним, и поднялся на гору, с табличками в руках.","4":"Господь написал на них то же самое, что и в первый раз, – Десять Заповедей, которые Он возвестил вам из огня, на горе, в день собрания всей общины. Он отдал таблички мне.","5":"Я повернулся, спустился с горы и положил их в сделанный мною ковчег. Там они и лежат – так повелел мне Господь.","6":"Покинув Беэрот – Бене–Яакан, сыны Израилевы пришли в Мосеру. Там умер Аарон, и там его похоронили. Вместо него священником стал его сын Элеазар.","7":"Оттуда они пришли в Гудгоду, а из Гудгоды – в Иотвату, где течет много ручьев.","8":"В ту пору Господь выделил племя Левия, поручив этому племени носить ковчег договора с Господом, предстоять пред Господом, служить Ему и благословлять именем Его. Это и поныне так.","9":"Вот почему племя Левия не получило надела и доли вместе с братьями. Их доля – Сам Господь, как и обещал им Господь, твой Бог.","10":"…Я пробыл на горе, как и в первый раз, сорок дней и сорок ночей. Господь послушал меня и на этот раз – не стал вас уничтожать.","11":"Он сказал мне: „Ступай, веди народ. Они должны прийти и овладеть страной, которую Я обещал отдать им, как поклялся в этом отцам их\".","12":"Израиль! Господь, ваш Бог, требует от вас лишь одного: чтобы вы боялись и чтили Господа, вашего Бога, всегда ходили путями Его, любили Его, служили Господу, вашему Богу, всем сердцем и всей душою,","13":"исполняли повеления и предписания Господа, которые я возвещаю вам ныне, для вашего блага.","14":"Господу, вашему Богу, принадлежат небеса и небеса небес, земля и все, что есть на земле,","15":"но Господь возлюбил только ваших прародителей. Он избрал вас, их потомков, из всех народов (это и поныне так).","16":"Так пусть сердца ваши станут обрезанными, впредь не будьте упрямы!","17":"Ибо Господь, ваш Бог, – это Бог над богами и Господин над господами. Он – Бог великий, могучий и грозный; Он беспристрастен и неподкупен.","18":"Он охраняет права вдов и сирот; Он любит переселенцев – дает им еду и одежду.","19":"Любите переселенцев и вы, ведь вы сами были переселенцами в Египте.","20":"Господа, твоего Бога, бойся и чти, Ему служи, оставайся верным Ему и клянись Его именем.","21":"Он – твоя слава, Он – твой Бог, Он совершил ради тебя великие и грозные дела, и ты видел их своими глазами.","22":"Когда ваши предки пришли в Египет, их было всего семьдесят человек, а ныне Господь, ваш Бог, сделал вас многочисленными, как звезды на небе."},"11":{"1":"Люби Господа, твоего Бога, всегда исполняй свой долг перед Ним, следуй Его предписаниям, законам и повелениям.","2":"Помните же! Не с детьми вашими случилось все это – они не знают и не видели ни уроков, преподанных Господом, вашим Богом, ни великих дел Его, ни руки Его могучей, десницы Его простертой,","3":"ни знамений и деяний Его в Египте. Что сделал Он с фараоном, царем египетским, и со всей его страной!","4":"Что сделал Он с египетским войском, с конями и колесницами! Когда египтяне погнались за вами, Он затопил их водами моря Суф – Он уничтожил их, и по сей день это так.","5":"Что Он делал для вас в пустыне, пока вы шли сюда!","6":"Что сделал Он с Датаном и Авирамом, сыновьями Элиава, потомка Рувима! Раскрыла земля свой зев, посреди израильского стана, и поглотила их, вместе с семьями, шатрами и скотом.","7":"А вы своими глазами видели все великие деяния, которые совершил Господь!","8":"Поэтому исполняйте все повеления, которые я возвещаю вам ныне, – и тогда вы будете сильны и придете в ту страну, в которую направляетесь, и овладеете ею.","9":"И долго будете вы жить на земле, которую Господь поклялся отдать отцам вашим и вам, их потомкам, – на земле, источающей молоко и мед.","10":"Страна, в которую вы идете и которой овладеете, не такова, как Египет, откуда вы ушли. В ту землю ты бросал семена и орошал ее, как орошают огород, – работая ногами.","11":"А страна, в которую вы идете и которой овладеете, – это горы и долины, орошаемые дождем с неба.","12":"Это страна, о которой заботится Господь, ваш Бог; Он присматривает за ней постоянно, в течение всего года.","13":"Если вы будете слушаться Моих повелений, которые Я возвещаю вам ныне, будете любить Господа, вашего Бога, и служить Ему всем сердцем и всей душой,","14":"то Я стану в срок посылать дождь на вашу землю, дождь осенний и весенний, – и у вас будет зерно, вино и оливковое масло.","15":"Я сделаю так, что на пастбищах вырастет трава для вашего скота, – и вам не придется голодать.","16":"Остерегайтесь соблазниться и, свернув с пути, пойти служить и поклоняться другим богам.","17":"Иначе Господь разгневается на вас и затворит небо, и не будет дождя, и земля не даст урожая, и вы быстро исчезнете из прекрасной страны, которую Господь отдает вам.","18":"Пусть эти мои слова всегда будут у вас в памяти и в мыслях. Повяжите их на руку как знак, пусть они будут повязкой у вас на лбу.","19":"Передайте их своим детям. Повторяй их постоянно – дома ты или в пути, ложишься или встаешь.","20":"Напиши их на дверных косяках твоего дома и на городских воротах.","21":"Тогда ваша жизнь и жизнь ваших детей на земле, которую Господь поклялся отдать отцам вашим, будет длиться долго – пока есть небо над землей.","22":"Если вы будете исполнять все повеления, которые я вам возвещаю, будете любить Господа, вашего Бога, всегда будете ходить путями Его, останетесь верными Ему,","23":"то Господь отдаст вам землю всех этих народов – вы овладеете землей народов, более многочисленных и сильных, чем вы.","24":"Всякое место, на которое ступит ваша нога, будет вашим: все земли от пустыни до Ливана, от Реки – реки Евфрат – до Западного моря станут вашими владениями.","25":"Никто не выстоит перед вами: Господь, ваш Бог, распространит по всякой стране, в которую вы вступите, страх и ужас перед вами, как Он вам и обещал.","26":"Вот, ныне я предлагаю вам благословение – или проклятие.","27":"Благословение – если вы будете слушаться повелений Господа, вашего Бога, которые я возвещаю вам ныне.","28":"Проклятие – если вы не послушаетесь повелений Господа, вашего Бога, свернете с того пути, на который я наставил вас ныне, и пойдете за другими богами, которых вы и не знали.","29":"Когда Господь, ваш Бог, приведет вас в страну, овладеть которой вы идете, провозгласите благословение на горе Гаризим, а проклятие – на горе Гевал.","30":"(Эти горы находятся по ту сторону Иордана, где дорога на запад, на земле ханаанеев, живущих в Араве , – близ Гилгала, неподалеку от дубов Морэ .)","31":"Ныне вы переходите Иордан, чтобы овладеть страной, которую отдает вам Господь, ваш Бог. Вы овладеете ею и будете в ней жить.","32":"Строго соблюдайте и исполняйте все предписания и законы, которые я возвещаю вам ныне!"},"12":{"1":"Вот предписания и законы – вы должны будете строго соблюдать и исполнять их в той стране, которую отдает вам во владение Господь, Бог отцов ваших. Исполняйте их все время, пока вы живете на земле.","2":"Уничтожьте все святилища, где народы, у которых вы отберете землю, служили своим богам, – на высоких горах, на холмах, под каждым ветвистым деревом.","3":"Их жертвенники – разрушьте, их священные камни – разбейте, дерева Ашеры – сожгите, изваяния их богов – низвергните! Искорените всякую память о них в тех местах.","4":"И не делайте ничего подобного для Господа, вашего Бога!","5":"Чтобы предстать пред Ним, приходите только на то место, которое Господь, ваш Бог, изберет на земле одного из ваших племен и сделает жилищем для Своего имени.","6":"Туда приходите, чтобы приносить всесожжения и жертвы, десятины и приношения, жертвы по обету и добровольные жертвы, первенцев крупного и мелкого скота.","7":"Там пируйте пред Господом, вашим Богом, и радуйтесь плодам своих трудов, веселитесь вместе со своими семьями, – ибо благословил вас Господь, ваш Бог.","8":"Вы не должны поступать так, как мы поступаем здесь ныне, – каждый по собственному разумению.","9":"Сейчас вы еще не пришли в ту землю, где будете жить спокойно, в тот надел, что отдает вам Господь, ваш Бог.","10":"Но вы перейдете Иордан и поселитесь в стране, которую Господь, ваш Бог, отдает вам во владение. Он дарует вам мирную жизнь, защитит от врагов, которые вас окружают; вы будете жить в безопасности.","11":"И тогда, чтобы приносить, как я вам повелел, всесожжения и жертвы, и десятину, и приношения, и лучшие жертвы по обетам, данным Господу, вы должны будете приходить лишь на то место, которое Господь, ваш Бог, изберет и сделает жилищем для Своего имени.","12":"Там веселитесь пред Господом, вашим Богом, и пусть вместе с вами веселятся ваши сыновья и дочери, рабы и рабыни, а также левит, живущий в вашем городе, – ведь у него, в отличие от вас, нет своего надела и доли.","13":"Смотри же, не совершай всесожжении где попало.","14":"Лишь на том месте, которое изберет Господь на земле одного из ваших племен, приноси жертвы всесожжения и совершай все то, что я тебе повелел.","15":"Однако ты можешь, когда захочешь, резать скот в своем городе и есть мясо – в зависимости от того, сколько будет у тебя скота по благословению Господа, твоего Бога. Всякий, и соблюдавший правила чистоты, и не соблюдавший их, может есть это мясо, словно мясо газели или лани.","16":"Только кровь не употребляйте в пищу, а выливайте на землю, как воду!","17":"Ты не должен есть у себя в городе десятину со своего зерна, вина и оливкового масла, а также мясо первенцев крупного и мелкого скота, жертву по обету, добровольную жертву и приношение.","18":"Ешь все это только пред Господом, твоим Богом, на том месте, которое изберет Господь, твой Бог, – и пусть вместе с тобою едят твои сыновья и дочери, рабы и рабыни, а также левит, живущий в твоем городе. Радуйся пред Господом, твоим Богом, наслаждаясь плодами своих трудов!","19":"И смотри, живя на земле своей, не забывай левита.","20":"Когда Господь, твой Бог, сделает ваши владения обширными, как Он и обещал, и ты захочешь и решишь поесть мяса, то можешь есть мясо – всегда, когда захочешь!","21":"Если далеко от тебя то место, которое Господь, твой Бог, изберет, чтобы там пребывало Его имя, – режь, как я повелел тебе, крупный или мелкий скот, что дал тебе Господь, и ешь у себя в городе, когда захочешь.","22":"Ешь это мясо, словно мясо газели или лани: его может есть и соблюдавший правила чистоты, и не соблюдавший их.","23":"Но ни в коем случае не употребляй в пищу кровь. Ведь кровь – это жизнь: не ешь жизнь вместе с мясом!","24":"Не употребляй кровь в пищу, а выливай на землю, как воду.","25":"Не употребляй ее – тогда тебе и твоим потомкам будет хорошо, ибо дела твои будут угодны Господу.","26":"А со священными приношениями и жертвами по обету ты должен приходить на то место, которое изберет Господь.","27":"Жертву всесожжения, и мясо, и кровь, сжигай на жертвеннике Господа, твоего Бога. Кровь пиршественной жертвы следует вылить на жертвенник Господа, твоего Бога, а ее мясо ты можешь съесть.","28":"Строго соблюдай и исполняй все эти заповеди, которые я тебе возвещаю. Тогда тебе и твоим потомкам всегда будет хорошо, ибо дела твои будут приятны и угодны Господу, твоему Богу.","29":"Господь, твой Бог, истребит народы, в чью страну ты идешь, чтобы овладеть ею, – и ты овладеешь этой страной и поселишься в ней.","30":"И тогда, после того как они будут уничтожены, берегись, не попади в ловушку – не расспрашивай про их богов, не говори: „Как эти народы служили своим богам? Я тоже буду так делать\".","31":"Не делай такого для Господа, твоего Бога! Ведь они творили для своих богов все те дела, которые мерзки и ненавистны Господу. Они даже сжигали ради своих богов собственных сыновей и дочерей!","32":"Строго соблюдайте и исполняйте все, что я вам повелел. Ничего к этому не добавляйте, ничего не убавляйте."},"13":{"1":"Если среди вас появится пророк или сновидец и пообещает знамение или чудо,","2":"и слова его сбудутся, а он при этом звал тебя идти за другими богами, за богами, которых ты и не знал, и служить им, –","3":"не слушай этого пророка или сновидца! Это Господь, ваш Бог, испытывает вас, чтобы узнать, любите ли вы Его всем сердцем и всей душой.","4":"Идите за Господом, вашим Богом, Его бойтесь и чтите, исполняйте Его повеления, Его слушайтесь, Ему служите, оставайтесь Ему верны!","5":"А тот пророк или сновидец должен быть предан смерти – за то, что он говорил неправду о Господе, вашем Боге, выведшем вас из Египта, освободившем вас из неволи, – за то, что он призывал вас свернуть с пути, на который вас наставил Господь, ваш Бог. Искорените зло!","6":"Если твой родной брат, или сын, или дочь, или любимая жена твоя, или друг, дорогой тебе, как жизнь, станет тайно уговаривать тебя идти и служить другим богам – богам, которых не знаешь ты и не знали твои отцы,","7":"богам живущих вокруг тебя народов, близких или далеких, населяющих землю от края и до края, –","8":"не соглашайся, не слушай этого человека! Не жалей его, не щади и не укрывай.","9":"Убей его! При его казни ты должен нанести ему удар первым, а все остальные – вслед за тобой.","10":"Забросайте его камнями насмерть – за то, что он уговаривал вас оставить Господа, вашего Бога, который вывел вас из Египта, из неволи!","11":"Весь Израиль узнает и затрепещет, и впредь никто из вас не будет так поступать!","12":"Если ты узнаешь, что в одном из ваших городов, отданных вам Господом, вашим Богом, чтобы вы жили в них,","13":"какие-то негодные люди уговорили прочих горожан идти и служить другим богам, богам, которых вы и не знали, –","14":"расследуй это дело, все выясни, расспроси получше. Если все окажется правдой и среди вас действительно была сотворена такая мерзость,","15":"то убейте мечом всех жителей этого города! Весь город и все, что в нем, включая скот, предайте заклятию – поразите мечом!","16":"Всю добычу соберите на площади – и сожгите город вместе со всей добычей как всецелую жертву Господу, вашему Богу. Пусть этот город навек обратится в безлюдный холм и никогда уже не будет отстроен.","17":"Пусть ничто из заклятого не прилипнет к вашим рукам! И тогда Господь оставит Свой гнев, и проявит к вам милосердие, и пожалеет вас, и сделает вас многочисленными, как и поклялся Он отцам вашим.","18":"Так будет, если вы станете слушаться Господа, вашего Бога, исполнять все Его повеления, которые я возвещаю вам ныне, и делать то, что угодно Господу, вашему Богу."},"14":{"1":"Вы – сыны Господа, вашего Бога. Не наносите себе порезов и не сбривайте волосы надо лбом, когда оплакиваете умерших.","2":"Ведь вы – святой народ у Господа, вашего Бога; Господь избрал вас из всех народов земли, чтобы вы были Его драгоценным достоянием.","3":"Не ешь никакой мерзости.","4":"Вот животные, которых вы можете есть: корова, овца, коза,","5":"лань, газель, косуля, дикий козел, дикий бык, антилопа, горный баран.","6":"Всех парнокопытных (животных с раздвоенными копытами), которые жуют жвачку, вы можете есть.","7":"Из животных, жующих жвачку и имеющих раздвоенные копыта, не ешьте верблюда, зайца и дамана (хотя они и жвачные, но раздвоенных копыт у них нет, и они нечисты для вас),","8":"а также свинью (хотя копыта у нее раздвоены, но жвачку она не жует, и она нечиста для вас). Мясо их не ешьте, к их трупам не прикасайтесь.","9":"Из водяных тварей ешьте тех, у кого есть плавники и чешуя.","10":"А тех, у кого нет плавников и чешуи, не ешьте – они нечисты для вас.","11":"Любую чистую птицу можете есть.","12":"А вот птицы, которых есть нельзя: орел, гриф, скопа,","13":"канюк, коршун, стервятники разных видов,","14":"вороны разных видов,","15":"страус, сипуха, чайка, соколы разных видов,","16":"неясыть, филин, сыч,","17":"сова, ястреб, баклан,","18":"аист, цапли разных видов, удод и летучая мышь.","19":"Все летающие насекомые нечисты для вас – их есть нельзя.","20":"А любую чистую летающую тварь вы можете есть.","21":"Не ешьте падаль. Отдавайте ее переселенцам, которые живут в ваших городах, – пусть они едят – или продавайте иноплеменникам. Ведь вы – святой народ у Господа, вашего Бога. Не вари козленка в молоке его матери.","22":"Отделяй десятину от всего урожая с твоих посевов – от всего, что вырастет на твоем поле. Делай так из года в год.","23":"Десятину с зерна, вина и оливкового масла, а также мясо первенцев крупного и мелкого скота ты должен есть пред Господом, твоим Богом, на том месте, которое Он изберет и сделает жилищем для Своего имени. Так ты научишься непрестанно бояться и чтить Господа, твоего Бога.","24":"Но может оказаться, что идти туда слишком долго и ты не в силах все это доставить, ибо далеко от тебя место, избранное Господом, твоим Богом, для того, чтобы там пребывало Его имя. Тогда, после того как благословит тебя Господь, твой Бог,","25":"обменяй все это на серебро и отправляйся, с серебром в руках, на то место, которое изберет Господь, твой Бог.","26":"А там на это серебро выменяй все, что захочешь, – крупный и мелкий скот, вино и пиво, все, что ни пожелаешь. И пируй там пред Господом, твоим Богом, веселись вместе со своей семьей!","27":"При этом не забывай левита, живущего в твоем городе, – ведь у него, в отличие от тебя, нет своего надела и доли.","28":"В конце каждого третьего года выноси всю десятину с твоего урожая за этот год к городским воротам.","29":"Пусть приходят левиты (ведь у них, в отличие от тебя, нет своего надела и доли), и переселенцы, и сироты, и вдовы, что живут в твоем городе, – и пусть они едят досыта! Тогда благословит тебя Господь, твой Бог, во всех делах твоих."},"15":{"1":"Каждый седьмой год совершайте прощение долгов.","2":"Оно состоит в том, что всякий заимодавец прощает ближнему его долг. Нельзя взыскивать долг с ближнего, с брата твоего, когда объявлено прощение долгов пред Господом.","3":"С иноплеменника ты можешь взыскать долг, а долги брата твоего прости.","4":"Впрочем, среди вас не должно быть бедных. Ведь в той стране, которую Господь, ваш Бог, отдает вам во владение, Господь щедро благословит вас –","5":"если вы будете слушаться Господа, вашего Бога, и строго соблюдать и исполнять все повеления, которые я возвещаю вам ныне.","6":"Когда Господь, ваш Бог, благословит вас, как Он и обещал, вы станете давать взаймы многим народам, а сами не будете брать в долг, станете властвовать над многими народами, а над вами никто не сможет властвовать!","7":"Если среди вас все же будут бедняки – кто-нибудь из братьев ваших, в каком-нибудь из ваших городов, в стране, которую Господь, ваш Бог, отдает вам, – то не будь бессердечен, пусть не будет рука твоя скупою для брата твоего, бедняка.","8":"Пусть рука твоя будет щедрой, дай ему в долг, сколько ему нужно, в соответствии с нуждами его.","9":"Смотри, как бы не закралась в твое сердце подлая мысль – ведь ты можешь, вспомнив, что близок седьмой год, год прощения долгов, посмотреть на брата твоего, бедняка, с неприязнью и отказать ему. Но тогда он воззовет к Господу и на тебе будет грех!","10":"Одолжи ему и не злись при этом – и благословит тебя Господь, твой Бог, во всех твоих делах и трудах.","11":"В стране всегда будут бедные, и поэтому я повелеваю тебе: пусть рука твоя будет щедрой, давай в долг братьям твоим, нуждающимся и беднякам в стране твоей.","12":"Если кто-то из твоих соплеменников, еврей или еврейка, попадет к тебе в рабство и проработает на тебя шесть лет, то на седьмой год ты должен отпустить этого человека на свободу.","13":"И отпускай его не с пустыми руками!","14":"Дай ему, что можешь, из своего стада, со своего гумна, из своей давильни: дай ему то, чем благословил тебя Господь, твой Бог.","15":"Помни, что ты и сам был рабом в Египте, а Господь, твой Бог, освободил тебя из неволи. Поэтому я и даю тебе ныне такое повеление.","16":"Если же раб скажет, что не хочет уходить от тебя, потому что полюбил тебя и твой дом и ему хорошо у тебя,","17":"то возьми шило и проколи ему ухо – так, чтобы шило воткнулось в дверь. И он станет твоим рабом навсегда. Так же поступи и с рабыней.","18":"А отпуская раба на свободу, ты не должен досадовать – все эти шесть лет он приносил тебе вдвое больше выгоды, чем наемный работник. И Господь, твой Бог, благословит тебя во всех делах твоих.","19":"Всякого первенца мужского пола, который рождается у крупного и мелкого скота, посвящай Господу, твоему Богу. Первенца коровы не используй в работе, первенца овцы не стриги.","20":"Каждый год ешь их пред Господом, твоим Богом, вместе с семьей твоей, на том месте, которое изберет Господь.","21":"Но если животное будет с изъяном – хромое, слепое или с другим серьезным изъяном – не приноси его в жертву Господу, твоему Богу,","22":"а съешь в своем городе. Его может есть и соблюдавший правила чистоты, и не соблюдавший их – словно это мясо газели или лани.","23":"Только кровь его не употребляй в пищу, а вылей на землю, как воду!"},"16":{"1":"Не забывай про месяц авив, совершай Пасху Господу, твоему Богу, ибо в месяце авиве, ночью, Господь, твой Бог, вывел тебя из Египта.","2":"Закалывай пасхальную жертву Господу, твоему Богу, – мелкий и крупный скот – на том месте, которое Господь изберет и сделает жилищем для Своего имени.","3":"Не ешь с пасхальной жертвой дрожжевой хлеб. Семь дней ты должен есть с нею пресный хлеб, хлеб бедствий, в память о том, что не мешкая уходил ты из Египта. Так ты будешь всю свою жизнь вспоминать день ухода из Египта!","4":"Семь дней нигде на вашей земле не должно быть закваски. Мясо животного, заколотого тобою вечером в первый день, не оставляй до утра.","5":"Не закалывайте пасхальную жертву ни в одном из городов ваших, отданных вам Господом, вашим Богом.","6":"Только на том месте, которое Господь, твой Бог, изберет и сделает жилищем для Своего имени, закалывай пасхальную жертву. Делай это вечером, на закате, – в тот самый час, в какой ты уходил из Египта.","7":"Приготовь и съешь мясо жертвы на том месте, которое изберет Господь, твой Бог, а утром отправляйся домой.","8":"Шесть дней ешь пресный хлеб, а седьмой день – праздник во имя Господа, твоего Бога, и работать нельзя.","9":"Отсчитав семь недель с начала жатвы,","10":"справляй праздник Недель во имя Господа, твоего Бога. Празднуй, расходуя по своему желанию то, чем благословит тебя Господь, твой Бог.","11":"Веселись пред Господом, твоим Богом, на том месте, которое Господь, твой Бог, изберет и сделает жилищем для Своего имени, – и пусть вместе с тобою веселятся твои сыновья и дочери, рабы и рабыни, левит, живущий в твоем городе, а также переселенцы, сироты и вдовы, которые живут среди вас.","12":"Помни, что ты и сам был рабом в Египте. Строго соблюдай и исполняй эти предписания.","13":"Справляй праздник Шалашей семь дней, когда закончишь работы на гумне и в давильне.","14":"Веселись на этом празднике – и пусть вместе с тобою веселятся твои сыновья и дочери, рабы и рабыни, а также левиты, переселенцы, сироты и вдовы, живущие в твоем городе.","15":"Семь дней празднуй во имя Господа, твоего Бога, на том месте, которое изберет Господь, – ведь Господь, твой Бог, благословил тебя богатым урожаем и удачей во всех делах. Веселись от души!","16":"Три раза в год все мужчины у вас должны представать пред Господом, вашим Богом, придя на то место, которое Он изберет, – делайте так в праздник Пресного Хлеба, в праздник Недель и в праздник Шалашей. И пусть никто не появляется пред Господом с пустыми руками!","17":"Пусть каждый приносит дар по своим возможностям, по мере того, насколько благословит его Господь, ваш Бог.","18":"Назначайте судей и старост, во всех городах ваших, отданных вам Господом, вашим Богом, – во всех ваших племенах – и пусть они судят справедливо.","19":"Не нарушай ничьих законных прав, суди беспристрастно. Не бери взяток, ибо взятка превращает мудрых людей в слепцов, а праведных делает лжецами.","20":"Стремись к справедливости, только к справедливости, и тогда ты будешь жив и будешь владеть той землей, которую отдает тебе Господь, твой Бог.","21":"Рядом с жертвенником Господа, твоего Бога, который ты воздвигнешь, не сажай дерево Ашеры – никакого дерева не сажай.","22":"Не ставь и священного камня. Господь, твой Бог, ненавидит это."},"17":{"1":"Не приноси в жертву Господу, твоему Богу, крупный или мелкий скот с изъяном, с каким бы то ни было недостатком, ибо для Господа, твоего Бога, это мерзость.","2":"Если у вас, в одном из городов, отданных вам Господом, вашим Богом, мужчина или женщина совершит дело, ненавистное Господу, вашему Богу, нарушит договор с Ним,","3":"пойдет и станет служить и поклоняться другим богам, или солнцу, или луне, или кому-то из воинства небесного, чего Я делать не велел,","4":"тогда, услышав и узнав о таком, расследуй это дело получше. Если все окажется правдой и в Израиле действительно была сотворена такая мерзость,","5":"то этого человека – мужчину или женщину, того, кто совершил это зло, – надо вывести к воротам и забросать камнями насмерть!","6":"Но казнить можно, если есть показания двух или трех свидетелей, а если свидетель только один – нельзя.","7":"При казни свидетели должны нанести удар первыми, а все остальные – вслед за ними. Искорените зло!","8":"Если трудно тебе будет решить дело, которое ты разбираешь в своем городе, – дело об убийстве, какое-нибудь обвинение, дело об увечьях – тогда отправляйся на то место, которое изберет Господь, твой Бог.","9":"Иди к священникам – левитам, к судье, что будет в то время, и спроси у них, и они объявят тебе свое решение.","10":"Ты должен будешь исполнить решение, объявленное тебе на том месте, которое изберет Господь, строго соблюдать и исполнять все, что тебе скажут.","11":"Сделай все по Закону, которому тебе научат, исполни решение, которое тебе возвестят. Не отклоняйся от него ни вправо, ни влево!","12":"А кто дерзнет ослушаться священника, служащего там Господу, твоему Богу, или судью, тот должен быть предан смерти. Искорените зло в Израиле!","13":"Пусть весь народ знает и трепещет, пусть впредь никто не поступает столь дерзко.","14":"Когда вы придете в страну, которую отдает вам Господь, ваш Бог, и овладеете ею, и поселитесь там, и захотите, подобно всем окрестным народам, поставить над собою царя,","15":"то можете поставить царя – того, кого изберет Господь, ваш Бог. Делайте царем одного из братьев ваших. Нельзя вручать власть чужаку, иноплеменнику!","16":"Царь не должен держать слишком много коней, не должен отправлять людей назад в Египет, чтобы приобрести побольше коней. Ведь Господь сказал вам: „Вы уже не вернетесь туда, по этому пути!\"","17":"У царя не должно быть слишком много жен, чтобы его сердце не склонилось к отступничеству. Он не должен иметь чересчур много серебра и золота.","18":"Когда он взойдет на престол, пусть перепишет для себя в свиток этот Закон, хранящийся у священников – левитов.","19":"И пусть всю жизнь держит его при себе и читает – и тогда он научится бояться и чтить Господа, своего Бога, неукоснительно исполнять этот Закон и все предписания.","20":"И не станет он возноситься над соплеменниками, не станет отклоняться от этих повелений ни вправо, ни влево – и тогда он и потомки его будут долго править Израилем."},"18":{"1":"У священников – левитов – у всего племени Левия – не будет, в отличие от прочих сынов Израилевых, своего надела и доли. Их доля – приношения Господу, ими они и будут кормиться.","2":"Не будет у племени Левия доли среди братьев. Их доля – Сам Господь, как Он и обещал им.","3":"Вот что народ должен отдавать священникам: кто приносит в жертву крупный или мелкий скот, тот пусть отдает священнику переднюю ногу животного, его челюсти и желудок.","4":"Отдавай священнику первое зерно, вино и масло от своего урожая, а также шерсть от первой стрижки овец.","5":"Ведь Господь, твой Бог, избрал его из всех ваших племен, чтобы он и его потомки всегда предстояли и служили имени Господа.","6":"Если левит, живущий в одном из ваших городов, где бы то ни было в Израиле, придет, когда захочет, на то место, которое изберет Господь,","7":"пусть служит имени Господа, своего Бога, как и братья его, левиты, предстоящие там пред Господом.","8":"Он должен получать пропитание наравне с ними, пусть даже у него есть средства от продажи родового имущества.","9":"Когда вы придете в страну, которую отдает вам Господь, ваш Бог, не приучайтесь делать мерзости, какие делают те народы.","10":"Пусть никто из вас не приносит в огненную жертву сына или дочь, пусть не будет среди вас ни прорицателей, ни гадателей, ни предсказателей, ни колдунов,","11":"ни заклинателей, ни тех, кто обращается к мертвецам и духам – ведунам, ни тех, кто взывает к мертвым.","12":"Всякий, кто это делает, мерзок Господу. За такие мерзости Господь, ваш Бог, отберет у тех народов землю – и отдаст ее вам.","13":"Будьте же непорочны пред Господом, вашим Богом!","14":"Народы, у которых вы отнимете землю, слушают гадателей и прорицателей, но не такое предназначил вам Господь, ваш Бог!","15":"Господь, ваш Бог, даст вам пророка, подобного мне, – это будет один из вас. Его и слушайте!","16":"Так исполнится то, о чем вы просили Господа, вашего Бога, у Хорива, в день собрания всей общины. Вы сказали тогда: „Не надо нам больше слушать голос Господа, нашего Бога, и смотреть на это великое пламя, иначе мы умрем!\"","17":"И Господь сказал мне: „Правильно они говорят.","18":"Я дам им пророка, подобного тебе, – это будет один из них. Я вложу слова Мои ему в уста, и он будет возвещать им все, что Я повелю возвестить.","19":"Если кто-нибудь не послушает слов Моих – слов, сказанных пророком от Моего имени, – Я Сам покараю такого человека!","20":"А пророк, который дерзнет говорить от Моего имени то, что Я не повелевал, или будет говорить от имени других богов, должен быть предан смерти\".","21":"Ты можешь подумать: „Но как же мы сумеем распознать то, чего Господь в действительности не говорил?\"","22":"Если то, что скажет пророк от имени Господа, не сбудется и не исполнится, – значит, этого Господь не говорил. Пророк сказал это лишь по дерзости своей – не бойся его!"},"19":{"1":"Когда Господь, ваш Бог, истребит народы, землю которых Он отдает вам, когда вы овладеете их землей и поселитесь в их городах и домах,","2":"то выделите там, в стране, которую отдает вам во владение Господь, ваш Бог, три города.","3":"Измерив расстояния, разделите страну, которую отдает вам Господь, ваш Бог, на три части, чтобы совершившие убийство могли найти убежище в этих городах.","4":"Вот в каком случае совершивший убийство может бежать в один из этих городов и спасти свою жизнь: если он убил неумышленно, а прежде между ним и убитым не было вражды.","5":"Например, человек пошел с кем-нибудь вдвоем в лес за дровами и занес топор, чтобы срубить дерево, а топор сорвался с рукоятки, попал в того и сразил насмерть. Такой человек может бежать в один из этих городов и спасти свою жизнь.","6":"И нельзя допустить, чтобы разгневанный мститель, погнавшись за ним, настиг его, из – за того что дорога слишком длинна, и убил! Ведь он не заслуживает смерти: прежде между ним и убитым вражды не было.","7":"Поэтому я повелеваю вам: выделите у себя три города.","8":"Если же Господь, ваш Бог, сделает ваши владения обширными, в чем Он поклялся отцам вашим, и отдаст вам всю страну, которую Он обещал отцам вашим","9":"(так будет, если вы станете неукоснительно исполнять все повеления, которые я возвещаю вам ныне, любить Господа, вашего Бога, всегда ходить путями Его), – тогда прибавьте к этим трем городам еще три города.","10":"И не прольется в стране, которую отдает вам Господь, ваш Бог, невинная кровь, и не будет на вас вины за кровь.","11":"Но если некто питал вражду к ближнему, подстерег его, напал на него и убил, а потом бежал в один из этих городов,","12":"то пусть старейшины города, где жил убийца, пошлют за ним, заберут его из того города, куда он бежал, и отдадут мстителю – чтобы убийца был предан смерти.","13":"Не жалейте его! Снимите с Израиля эту вину, пролитие невинной крови, – и будет вам хорошо.","14":"Не сдвигай межу ближнего, проведенную предками в ваших владениях, – в стране, которая отдана вам Господом, вашим Богом.","15":"На суде один свидетель не может обвинить человека ни в каком преступлении или проступке, ни в какой провинности. Обвинение будет законным лишь тогда, когда есть два или три свидетеля.","16":"Если некий лжесвидетель обвинит невинного,","17":"то оба они должны предстать пред Господом – перед священниками и судьями, что будут в то время.","18":"И если судьи, тщательно расследовав дело, обнаружат, что этот свидетель дал ложные показания, возвел на брата своего напраслину,","19":"сделайте с ним то, что он готовил брату своему. Искорени зло!","20":"Все остальные узнают об этом и затрепещут, и впредь никто из вас не будет так поступать.","21":"Не поддавайся жалости! Жизнь за жизнь. Глаз за глаз. Зуб за зуб. За руку – рука. За ногу – нога."},"20":{"1":"Когда вы пойдете сражаться с врагом и увидите коней и колесницы – войско более многочисленное, чем ваше, – не бойтесь. Ведь с вами Господь, ваш Бог, который вывел вас из Египта!","2":"Пусть перед боем священник обратится к войску","3":"и скажет: „Слушай, Израиль! Сегодня вы вступите в бой с врагом. Не будьте малодушны, не бойтесь, не пугайтесь, не ужасайтесь!","4":"Господь, ваш Бог, идет вместе с вами, чтобы сразиться с врагом за вас и даровать вам победу\".","5":"А старосты пусть скажут войску:, Если кто-то из вас построил себе дом и еще не обновил его, пусть возвращается домой. Иначе может случиться так, что он падет в бою и другой человек обновит его дом.","6":"Если кто-то из вас насадил виноградник и еще не собрал урожай, пусть возвращается домой. Иначе может случиться так, что он падет в бою и другой соберет урожай с его виноградника.","7":"Если кто-то из вас обручился с женщиной и еще не женился на ней, пусть возвращается домой. Иначе может случиться так, что он падет в бою и другой женится на ней\".","8":"Затем старосты должны сказать войску: „Если кто-то из вас боязлив и малодушен, пусть возвращается домой, чтобы своей трусостью не заразить других\".","9":"После того как старосты закончат свои речи перед войском, должны быть назначены предводители, которые встанут во главе войска.","10":"Подойдя к городу, с которым вы собираетесь воевать, сперва предложите этому городу сдаться без боя.","11":"Если предложение будет принято и вам откроют ворота, то пусть все, кто живет в городе, впредь несут трудовую повинность – работают на вас.","12":"Если же город не сдастся и решится воевать с вами, начинайте осаду.","13":"Когда Господь, ваш Бог, отдаст город в ваши руки, всех мужчин в нем поразите мечом.","14":"А женщин, детей, скот и все, что есть в городе, можете взять себе как добычу. Пользуйтесь всем тем, что возьмете у врага как добычу, – тем, что отдаст вам Господь, ваш Бог!","15":"Так вы должны поступать с теми городами, которые находятся далеко от вас и не принадлежат здешним народам.","16":"А в городах здешних народов, чью землю Господь, ваш Бог, отдает вам во владение, не оставляйте в живых никого!","17":"Предайте их всех заклятью и уничтожьте – хеттов, амореев, ханаанеев, периззеев, хиввеев и евусеев – как повелел вам Господь, ваш Бог.","18":"Иначе они научат вас творить все те мерзости, которые они творят для своих богов, и вы согрешите пред Господом, вашим Богом.","19":"Если вы, стремясь захватить город, долго осаждаете его, не уничтожайте деревья в его окрестностях, не рубите их топором. Ешьте их плоды, а деревья не срубайте. Разве деревья в поле это люди, чтобы тоже оказаться в осаде?","20":"Уничтожайте лишь те деревья, о которых вы знаете, что они не приносят съедобных плодов. Рубите их и сооружайте из них приспособления для осады вражеского города – пока он не падет."},"21":{"1":"Если в стране, которую Господь, ваш Бог, отдает вам во владение, будет найдено в поле тело убитого, но неизвестно будет, кто убил его,","2":"пусть ваши старейшины и судьи придут и, измерив расстояние от тела до окрестных городов,","3":"определят, какой город ближе всего к найденному телу Пусть старейшины этого города выберут молодую корову, которая еще не использовалась в работе и не знает ярма.","4":"Пусть старейшины приведут эту корову к непересыхающему ручью, на берегах которого еще никто не пахал и не сеял, и там, у ручья, пусть сломают ей шею.","5":"Затем пусть подойдут священники, потомки Левия, ибо их избрал Господь, ваш Бог, чтобы они служили Ему и благословляли именем Господа, и по их приговору решается всякая тяжба и всякое дело об увечьях.","6":"Пусть все старейшины города, ближайшего к найденному телу, омоют свои руки над коровой, которой сломали шею у ручья,","7":"и скажут: „Наши руки не проливали эту кровь, наши глаза не видели, как она пролилась.","8":"О Господь, оправдай Свой народ, сынов Израилевых, народ, освобожденный Тобою из неволи! Не возлагай на сынов Израилевых, народ Свой, вину за пролитие невинной крови\". И тогда не падет на них вина за эту кровь.","9":"Так вы снимете с себя вину за пролитие невинной крови, сделав то, что угодно Господу.","10":"Когда вы пойдете сражаться с врагами, и Господь, ваш Бог, отдаст их в ваши руки, и вы поведете невольников в плен,","11":"может случиться, что ты увидишь среди невольников красивую женщину, она понравится тебе и ты захочешь на ней жениться.","12":"Тогда приведи ее к себе домой, пусть она обреет голову, обрежет ногти,","13":"снимет одежду пленницы и месяц живет в твоем доме, оплакивая отца и мать. После этого ты можешь войти к ней – стать ее мужем, а она будет тебе женой.","14":"Если она станет тебе нежеланна, отпусти ее на свободу. Ты не должен продавать ее, не должен на ней наживаться, если ты овладел ею.","15":"Если у человека две жены и одну он любит, а другую нет, и обе, любимая и нелюбимая, родили ему сыновей, причем первенец его – сын нелюбимой,","16":"то этот человек, распределяя между сыновьями наследство, не может отдать долю первенца сыну любимой жены за счет настоящего первенца, сына нелюбимой.","17":"Он обязан признать сына нелюбимой жены первенцем и выделить ему из всего, что имеет, двойную долю. Ведь этот сын – первый плод его мужской силы, и права первенца за ним.","18":"Если у кого-то есть упрямый и непокорный сын, который ни отцу ни матери не повинуется, и сколько ни вразумляют они его, он их не слушает,","19":"пусть отец и мать приведут его к старейшинам города, к городским воротам,","20":"и скажут старейшинам: „Наш сын упрям и непокорен. Он нам не повинуется, предается обжорству и пьянству\".","21":"И пусть жители города забросают его камнями насмерть. Искорените зло! Весь Израиль узнает об этом – и затрепещет.","22":"Если человек совершил преступление, которое карается смертью, и был казнен, и вы повесили его тело на столбе,","23":"то тело не должно оставаться на столбе ночью, оно должно быть похоронено в тот же день. Повешение – проклятие духа! Не оскверняйте землю, которую Господь, ваш Бог, отдает вам во владение."},"22":{"1":"Если ты увидишь, что заблудился принадлежащий брату твоему бык, либо овца, не проходи мимо – верни животное хозяину.","2":"Если он живет далеко или же ты не знаешь, кто хозяин скотины, возьми ее к себе, пусть она остается у тебя, пока не явится хозяин – и тогда верни ее.","3":"Так же поступай и с ослом, и с одеждой, и со всем тем, что пропало у брата твоего и найдено тобою. Ты не должен проходить мимо!","4":"Если увидишь, что принадлежащий брату твоему осел или бык упал на дороге, не проходи мимо, помоги брату твоему поднять его.","5":"На женщине не должно быть ничего того, что носят мужчины, а мужчина не должен надевать женскую одежду. Всякий, кто делает так, мерзок Господу, твоему Богу.","6":"Если в пути ты нашел гнездо, на дереве или на земле, а в гнезде есть птенцы или яйца, и птица сидит при птенцах или на яйцах, то не забирай мать вместе с потомством.","7":"Отпусти птицу, а потомство ее можешь забрать. Тогда тебе будет хорошо и долгой будет твоя жизнь.","8":"Когда строишь новый дом, сделай по краям крыши ограду, чтобы никто не упал с крыши и на твой дом не легла вина за кровь.","9":"Не сей в своем винограднике другой вид семян, иначе все это окажется под запретом – и посеянное тобой, и урожай с виноградника.","10":"Не паши на воле и осле, впряженных в один плуг.","11":"Не носи одежду, сотканную из двух разных видов нити – из шерсти и льна.","12":"Сделай кисти на всех четырех углах твоего плаща.","13":"Если некто женится и ляжет с женой, и она ему не понравится,","14":"и он начнет обвинять ее в бесчестии и распространять о ней худую молву, говоря: „Я взял ее в жены, но когда лег с ней, то обнаружил, что она не девственница\", –","15":"тогда отец и мать девушки должны принести доказательство ее девственности к городским воротам и показать старейшинам города.","16":"Пусть отец ее скажет старейшинам: „Я отдал свою дочь замуж за этого человека, а она ему не понравилась,","17":"и он обвиняет ее в бесчестии, говоря, что дочь моя не была девственницей. Но вот доказательство ее девственности!\" – и пусть развернут одежду перед старейшинами города.","18":"И старейшины подвергнут этого человека наказанию,","19":"а также взыщут с него сто шекелей серебра и отдадут их отцу девушки. Ведь этот человек распускал худую молву о девственнице – израильтянке! И она останется его женой – он уже не имеет права с нею развестись, всю свою жизнь.","20":"Но если обвинение окажется справедливым, если она действительно не была девственницей,","21":"то пусть приведут ее к двери отцовского дома и пусть жители города забросают ее там камнями насмерть. Она совершила гнусное дело в Израиле – развратничала в доме своего отца. Искорените зло!","22":"Если мужчину застали лежащим с чужой женой, то оба должны быть преданы смерти – и мужчина, сделавший такое, и сама женщина. Искорените зло в Израиле!","23":"Если в городе мужчина встретит невинную девушку, обрученную с другим человеком, и ляжет с ней,","24":"то вы должны привести обоих к городским воротам и забросать камнями насмерть: девушку – за то, что она не звала на помощь, хотя дело было в городе, а мужчину – за то, что он обесчестил жену ближнего. Искорените зло!","25":"Если же вне города мужчина встретит девушку, обрученную с другим человеком, схватит ее и ляжет с ней, то смерти следует предать только мужчину, который сделал такое.","26":"Девушку не наказывайте, она не совершила ничего, что заслуживало бы смерти: случай с нею подобен тому, как если бы некто напал на ближнего и убил его.","27":"Мужчина встретил ее в поле, и даже если обрученная девушка кричала, некому было прийти к ней на помощь.","28":"Если мужчина встретит невинную девушку, еще не обрученную, схватит ее и ляжет с ней, и их застанут,","29":"то мужчина, сделавший такое, должен уплатить отцу девушки пятьдесят шекелей серебра и взять ее в жены, потому что он обесчестил ее. Он не имеет права с ней развестись, всю свою жизнь.","30":"Никто не может жениться на жене своего отца – нельзя поднимать край одежды отца."},"23":{"1":"Мужчина с раздавленными яичками или с отрезанным членом не может войти в общину Господа.","2":"Рожденный от недозволенной связи не может войти в общину Господа, и потомки его, даже в десятом поколении, тоже не могут.","3":"Аммонитяне и моавитяне не могут войти в общину Господа, и потомки их тоже не могут, даже в десятом поколении, никогда!","4":"Ведь они не встречали вас на дороге с хлебом и водой, когда вы шли из Египта. Они наняли Валаама, сына Беора, из Петора в АрамНахараиме, чтобы он проклял вас!","5":"(Но Господь, ваш Бог, не пожелал слушать Валаама и обратил проклятие в благословение, ибо Господь, ваш Бог, любит вас.)","6":"Поэтому никогда, пока вы живы, не делайте ничего, что принесло бы им мир и благополучие.","7":"Не отвергайте эдомитянина, ибо он брат ваш. Не отвергайте египтянина, ибо вы были переселенцами в его стране.","8":"Их потомки в третьем поколении могут войти в общину Господа.","9":"Когда вы пойдете воевать с врагом, остерегайтесь любой скверны.","10":"Если кто-то из вас сделается нечист из – за случившегося с ним ночью, то пусть он выйдет за пределы стана. Он не должен входить в стан.","11":"А вечером пусть омоется водой, и когда зайдет солнце, он может вернуться.","12":"У вас должно быть место вне стана, куда вы могли бы выходить по нужде.","13":"Каждый должен иметь при себе лопатку, чтобы, присев там, вырыть ямку, а потом закопать нечистоты.","14":"Ведь Господь, ваш Бог, идет вместе с вашим войском, избавляя вас и даруя вам победы над врагами. Поэтому ваш стан должен быть свят, чтобы не увидел Он у вас ничего непристойного и не отвернулся бы от вас.","15":"Не выдавайте хозяину раба, который бежал от хозяина к вам.","16":"Пусть он живет у вас – где захочет, в одном из ваших городов, там, где ему понравится. Не притесняйте его.","17":"Среди дочерей Израиля не должно быть публичных женщин; среди сынов Израиля не должно быть „посвященных\".","18":"При исполнении обетов не вноси в Храм Господа, твоего Бога, ни заработанное продажной женщиной, ни плату за пса. Оба они мерзки Господу, твоему Богу.","19":"Не давай брату твоему в долг под проценты ни серебра, ни съестного, ничего того, что дают под проценты.","20":"Иноплеменнику ссужай под проценты, а брату твоему – нет, и тогда благословит тебя Господь, твой Бог, во всех трудах твоих в той стране, в которую вы идете и которой овладеете.","21":"Если ты дал обет Господу, твоему Богу, исполняй не откладывая, ибо Господь, твой Бог, непременно взыщет с тебя обещанное, и на тебе будет грех.","22":"Если же не станешь давать обет, не будет на тебе греха.","23":"Строго соблюдай и исполняй то, что ты пообещал, – те обеты, которые ты добровольно дал Господу, твоему Богу, – то, что изрекли уста твои.","24":"Если ты придешь в чужой виноградник, можешь есть виноград, сколько хочешь, досыта, но в корзину не собирай.","25":"Если придешь на чужую ниву, можешь срывать колосья руками, но не срезай чужих колосьев серпом."},"24":{"1":"Положим, некто женился и стал жить с женой, но она ему не понравилась, ибо он нашел в ней что-то неподобающее, и он дал жене письмо о разводе и отослал ее прочь из своего дома,","2":"и она, покинув его дом, вышла замуж за другого человека.","3":"Если она не понравилась и второму мужу и тот, дав ей письмо о разводе, отослал ее прочь из своего дома – или если второй ее муж умер –","4":"то первый муж, который развелся с ней, не может снова взять ее в жены, ибо она сделалась нечистой. Для Господа это было бы мерзостью! Не оскверняйте грехом землю, которую Господь, ваш Бог, отдает вам во владение.","5":"Если человек только что женился, то он не должен уходить на войну, не следует возлагать на него и других обязанностей. Пусть он будет свободен в течение одного года – пусть остается дома и радует жену, которую он взял себе.","6":"Нельзя брать в залог ручные жернова (или даже один только верхний жернов) – это означало бы взять в залог человеческую жизнь.","7":"Если обнаружится, что некто похитил человека, одного из братьев своих, сынов Израилевых, и нажился на нем – продал его, то этот похититель должен быть предан смерти. Искорените зло!","8":"В случае кожной болезни строжайшим образом соблюдайте и исполняйте все то, чему вас научат священники – левиты. Поступайте в точности так, как я повелел им.","9":"Помни, что сделал Господь, твой Бог, с Мирьям, когда вы шли из Египта.","10":"Если ты одалживаешь ближнему что-либо, не входи в его дом за залогом.","11":"Постой на улице, пусть тот, кому ты одалживаешь, сам вынесет тебе залог.","12":"Если он беден, то не ложись спать, пока его залог у тебя.","13":"Верни ему залог до захода солнца, чтобы он лег спать, укрывшись своим плащом, и благословил бы тебя. Тогда ты будешь праведен пред Господом, твоим Богом.","14":"Не притесняй наемного работника, бедного и обездоленного, будь то один из братьев твоих или же переселенец, живущий в твоей стране, в одном из ваших городов.","15":"Отдавай ему заработок в тот же день, еще до захода солнца, ибо он беден и от этого заработка зависит его жизнь. Иначе он воззовет к Господу, жалуясь на тебя, и тогда на тебе будет грех!","16":"Отцов нельзя предавать смерти за вину сыновей, а сыновей – за вину отцов. Человек может быть предан смерти лишь за то преступление, которое совершил он сам.","17":"Не попирай прав переселенца и сироты, не бери в залог одежду вдовы.","18":"Помни, что ты и сам был рабом в Египте, а Господь, твой Бог, освободил тебя из неволи. Поэтому я и даю тебе такое повеление.","19":"Если во время жатвы ты забудешь на своем поле сноп, не возвращайся за ним – пусть он достанется переселенцу, сироте или вдове. И тогда Господь, твой Бог, благословит тебя во всех делах твоих.","20":"Когда обобьешь свои оливковые деревья, не ищи на ветвях оставшиеся оливки, пусть они достанутся переселенцу, сироте или вдове.","21":"Собрав свой виноград, не ищи на лозе оставшиеся ягоды, пусть они достанутся переселенцу, сироте или вдове.","22":"Помни, что ты и сам был рабом в Египте. Поэтому я и даю тебе такое повеление."},"25":{"1":"Положим, двое спорящих явились в суд – и суд рассудил их, объявив правого правым, а виновного виновным.","2":"И вот, если виновный подлежит битью, пусть судья распорядится, чтобы его тут же, у него на глазах, положили на землю и дали ему столько ударов, сколько следует за его вину.","3":"Но нельзя назначать более сорока ударов, чтобы брат твой не был унижен перед тобою чрезмерным битьем.","4":"Не завязывай рот волу, когда он молотит.","5":"Если братья жили вместе и один из них умер, не оставив сына, то жена умершего не должна выходить замуж за чужого человека. Пусть брат ее мужа войдет к ней – пусть женится на ней, чтобы заменить брата.","6":"Первенец, которого она родит, будет считаться потомком умершего, чтобы имя умершего не исчезло в Израиле.","7":"Если же этот человек не пожелает взять свою невестку в жены, пусть она придет к городским воротам и скажет старейшинам: „Мой деверь не желает сохранить имя брата в Израиле, он отказывается заменить брата!\"","8":"Тогда старейшины города должны призвать его, чтобы уговорить. Если он будет упорствовать, не желая жениться на ней,","9":"пусть невестка подойдет к нему, на глазах у старейшин, снимет с его ноги сандалию, плюнет ему в лицо и скажет: „Вот так поступают с тем, кто не созидает дом брату своему!\"","10":"А произошедший от него род получит среди сынов Израилевых прозвище: Род Разутого.","11":"Если двое подрались, а жена одного из них пришла, чтобы спасти мужа от того, кто бьет его, и схватила того человека за срам,","12":"то отрубите ей руку – не жалейте ее!","13":"Не держи у себя в сумке двух разных каменных гирек, побольше и поменьше.","14":"Не держи в доме двух разных мерных сосудов, побольше и поменьше.","15":"Гирька у тебя должна быть правильного, точного веса, а мерный сосуд – правильного, точного размера, и тогда долгой будет твоя жизнь на земле, которую отдает тебе Господь, твой Бог.","16":"А всякий, кто делает подобные вещи, – всякий обманщик – мерзок Господу, твоему Богу.","17":"Помните о том, как поступили с вами амалекитяне, когда вы шли из Египта!","18":"Встретив вас, они напали на вас сзади и перебили всех отставших – вы были утомлены и обессилены, а амалекитяне не боялись Бога.","19":"Когда Господь, ваш Бог, дарует вам мирную жизнь в стране, которую Он отдает вам во владение, избавит от врагов, которые вас окружают, – сотрите под небесами имя амалекитян. Не забудьте!"},"26":{"1":"Когда вы придете в страну, которую Господь, ваш Бог, отдает вам во владение, когда вы овладеете ею и поселитесь там,","2":"возьми первые плоды урожая, собранного тобою с той земли, которую отдал тебе Господь, твой Бог, положи их в корзину и приди на то место, которое Господь, твой Бог, изберет и сделает жилищем для Своего имени.","3":"Подойди к священнику, который будет в то время, и скажи: „Ныне я возвещаю Господу, твоему Богу, что я пришел в ту страну, о которой Господь поклялся отцам нашим, что отдаст ее нам\".","4":"Священник возьмет у тебя корзину и поставит ее перед жертвенником Господа, твоего Бога,","5":"а ты скажи пред Господом, твоим Богом: „Прародитель мой был скиталец – арамей. Он ушел в Египет с немногими людьми и жил там как переселенец. Там от него произошел народ великий, сильный и многочисленный.","6":"Египтяне же относились к нам плохо, угнетали нас и принуждали к тяжелой работе.","7":"Тогда мы воззвали к Господу, Богу отцов наших, и Господь услышал нас, увидел наши бедствия, страдания и мучения.","8":"И Господь вывел нас из Египта рукой Своей могучей, десницей простертой, совершив великие и страшные деяния, и знамения, и чудеса.","9":"Он привел нас сюда и отдал нам эту землю – землю, источающую молоко и мед.","10":"И вот я принес первые плоды урожая с земли, которую Ты, Господь, отдал мне\". Потом поставь корзину пред Господом, твоим Богом, и склонись пред Ним.","11":"Веселись, пользуясь всем тем, что дал тебе и твоей семье Господь, твой Бог, – и пусть вместе с тобой веселятся левит и переселенец, которые живут среди вас.","12":"В третий год, год десятины, когда ты отделишь от всего своего урожая десятину и отдашь ее левиту, переселенцу, сироте и вдове, чтобы они, в твоем городе, ели досыта, –","13":"тогда скажи пред Господом, твоим Богом: „Я удалил из своего дома святую долю и отдал ее левиту, переселенцу, сироте и вдове – сделал все так, как Ты мне повелел. Ни одного из Твоих повелений я не нарушил, ни одним из них не пренебрег.","14":"Я не ел святой доли, когда оплакивал кого-нибудь, не отделял ее, когда бывал нечист, не отдавал ее мертвому. Я слушался Господа, моего Бога, – делал все так, как Ты мне повелел.","15":"Взгляни же из святого жилища Твоего, с небес, и благослови Свой народ, Израиль, и ту землю, которую Ты нам отдал, как и обещал отцам нашим, – землю, источающую молоко и мед\".","16":"Ныне Господь, ваш Бог, повелевает вам соблюдать эти предписания и законы. Исполняйте их неукоснительно – всем сердцем, всей душой!","17":"Вы сказали ныне, что Господь – ваш Бог, что вы будете ходить путями Его, будете исполнять Его предписания, повеления и законы, будете слушаться Его.","18":"А Господь ныне сказал, что вы будете Его драгоценным достоянием, как Он и обещал вам, и что вы должны исполнять все Его повеления,","19":"и что Он возвысит вас над всеми народами, которые Он сотворил, и дарует вам честь, славу и великолепие, и вы будете святым народом Господа, вашего Бога, как Он и обещал»."},"27":{"1":"Моисей, вместе со старейшинами Израиля, велел народу: «Исполняйте все повеления, которые я возвещаю вам ныне.","2":"Когда вы перейдете Иордан и вступите в страну, которую отдает вам Господь, ваш Бог, воздвигните там большие камни, побелите их известью","3":"и запишите на них этот Закон. Сделайте это, когда перейдете на ту сторону, чтобы вступить в землю, которую отдает вам Господь, ваш Бог, в землю, источающую молоко и мед, как и обещал вам Господь, Бог отцов ваших.","4":"Перейдя Иордан, воздвигните на горе Гевал камни, о которых я говорю вам ныне, и побелите их известью.","5":"Воздвигните там жертвенник Господу, вашему Богу, жертвенник из камней, которых не касалось железное орудие.","6":"Воздвигните жертвенник Господу, вашему Богу, из необработанных камней – и совершайте на нем всесожжения Господу, вашему Богу,","7":"приносите на нем пиршественные жертвы, и ешьте, и веселитесь пред Господом, вашим Богом!","8":"Запишите на камнях этот Закон, отчетливо и ясно».","9":"Моисей, вместе со священниками – левитами, сказал всему Израилю: «Молчи и внимай, Израиль! Сегодня вы стали народом Господа, вашего Бога.","10":"Слушайтесь же Господа, вашего Бога, исполняйте Его повеления и предписания, которые я возвещаю вам ныне».","11":"В тот день Моисей дал народу такое повеление:","12":"«Когда вы перейдете Иордан, пусть племена Симеона, Левия, Иуды, Иссахара, Иосифа и Вениамина встанут на горе Гаризим и благословят народ.","13":"А племена Рувима, Гада, Асира, Завулона, Дана и Неффалима пусть встанут на горе Гевал и провозгласят проклятия.","14":"Пусть левиты громко скажут всем сынам Израилевым:","15":"„Кто сделает изваяние, литую статую, – мерзость для Господа, творение ремесленника, – и тайно установит, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","16":"„Кто оскорбит отца или мать, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","17":"„Кто сдвинет межу ближнего, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","18":"„Кто поведет слепого по неверной дороге, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","19":"„Кто попирает права переселенца, сироты и вдовы, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","20":"„Кто ляжет с женой отца – поднимет край одежды отца – да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","21":"„Кто ляжет с каким-либо животным, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","22":"„Кто ляжет с сестрой, дочерью своего отца или своей матери, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","23":"„Кто ляжет с тещей, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","24":"„Кто тайно убьет ближнего, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","25":"„Кто возьмет мзду за убийство, за пролитие невинной крови, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\"","26":"„Кто не станет следовать этому Закону и исполнять его, да будет проклят!\" И пусть весь народ скажет: „Да будет так!\""},"28":{"1":"Если вы будете слушаться Господа, вашего Бога, и строго соблюдать и исполнять все Его повеления, которые я возвещаю вам ныне, то Господь, ваш Бог, возвысит вас над всеми народами земли.","2":"Вот благословения, которые снизойдут на тебя и сбудутся, если ты будешь слушаться Господа, твоего Бога.","3":"Благословен ты будешь в городе и благословен в поле.","4":"Благословенно будет твое потомство, и урожай твоей земли, и приплод твоего скота – приплод коров, приплод овец и коз.","5":"Благословенны будут твоя корзина и твоя квашня.","6":"Благословен ты будешь, когда придешь домой, и благословен, когда выйдешь из дому.","7":"Господь сделает так, что вы разобьете врагов, которые на вас нападут: по одной дороге пойдут они на вас, а побегут от вас по семи дорогам.","8":"Господь ниспошлет на вас благословение – на ваши амбары, на все ваши труды. Господь, ваш Бог, благословит вас на земле, которую Он отдает вам!","9":"Господь сделает вас Своим святым народом, как Он и поклялся вам, – если вы будете исполнять повеления Господа, вашего Бога, и ходить путями Его.","10":"Тогда все народы земли увидят, что над вами провозглашено имя Господа, и будут вас бояться.","11":"Господь пошлет вам все в изобилии – и потомство, и приплод скота, и урожай на полях – на той земле, которую Господь обещал отдать вам, поклявшись в этом отцам вашим.","12":"Господь откроет ради вас Свою богатую сокровищницу, небо, и в срок пошлет дождь вашей земле, и благословит все ваши труды. Вы будете давать взаймы многим народам, а сами не будете брать в долг.","13":"Господь сделает вас головой, а не хвостом, вы всегда будете наверху, а не внизу – если будете слушаться повелений Господа, вашего Бога, которые я возвещаю вам ныне, строго соблюдать и исполнять их,","14":"если не будете уклоняться ни вправо ни влево от всех заповедей, которые я возвещаю вам ныне, если не пойдете за другими богами, не станете им служить.","15":"А вот проклятия, которые падут на тебя и сбудутся, если ты не станешь слушаться Господа, твоего Бога, не будешь строго соблюдать и исполнять все Его повеления и предписания, которые я возвещаю тебе ныне.","16":"Проклят ты будешь в городе и проклят в поле.","17":"Прокляты будут твоя корзина и твоя квашня.","18":"Проклято будет твое потомство, и урожай твоей земли, и приплод коров, и приплод овец и коз.","19":"Проклят ты будешь, когда придешь домой, и проклят, когда выйдешь из дому.","20":"Господь пошлет на вас проклятие, и смятение, и осуждение во всех ваших трудах и делах, и будете вы уничтожены, быстро погибнете, из – за своих злых деяний – из – за того, что вы оставили Меня.","21":"Господь нашлет на вас чуму, и вы исчезнете с той земли, в которую вы идете, чтобы овладеть ею.","22":"Господь поразит вас чахоткой, горячкой и лихорадкой, жаром и засухой, суховеем и спорыньей, и эти бедствия будут преследовать вас, пока не погубят.","23":"Небо у вас над головами станет медным, а земля у вас под ногами – железной.","24":"Господь пошлет на вашу землю дождь из пыли, и дождь этот будет падать на вас с неба, пока вы не погибнете.","25":"Господь сделает так, что враги разобьют вас: по одной дороге пойдете вы на них, а побежите от них по семи дорогам. Ваша судьба вызовет ужас во всех царствах земли.","26":"Трупы ваши станут добычей птиц небесных и зверей земных, которых некому будет отгонять.","27":"Господь поразит тебя египетскими нарывами, опухолями, паршой и чесоткой, и ты не сможешь излечиться.","28":"Господь поразит тебя безумием и слепотой, и спутаются твои мысли.","29":"Средь бела дня ты будешь ходить на ощупь, как слепой во тьме. Не будет тебе удачи в делах твоих. Ты всегда будешь угнетен и обобран, и никто тебе не поможет.","30":"Ты обручишься, но с твоею невестой ляжет другой, построишь дом, а жить в нем не будешь, насадишь виноградник, а урожай не соберешь.","31":"Твоего быка зарежут у тебя на глазах, но ты не вкусишь его мяса; твоего осла отнимут у тебя и уже не вернут; твои овцы и козы достанутся врагам твоим, и никто тебе не поможет.","32":"Твои сыновья и дочери будут отданы чужому народу, и ты проглядишь все глаза, день за днем ожидая их возвращения, но сделать ничего не сможешь.","33":"Народ, о котором ты и не знал, станет пожирать плоды твоей земли и все нажитое тобою; каждый день тебя будут угнетать и мучить.","34":"И ты сойдешь с ума от увиденного.","35":"Господь поразит тебя страшными нарывами на коленях и голенях, и ты не сможешь излечиться; они покроют тебя от пят до макушки.","36":"Господь отведет вас, вместе с царем, которого вы поставите над собою, к народу, о котором ни вы, ни отцы ваши и не знали, и там вы будете служить другим богам – камням и деревяшкам.\"Ужасным примером, притчей и посмешищем будете вы для всех народов, к которым изгонит вас Господь.","38":"Много семян посеете вы на поле, а хлеба соберете мало, потому что сожрет его саранча.","39":"Вы насадите виноградники и будете возделывать их, а вина не выпьете и не запасете, потому что виноград ваш будет съеден червем.","40":"По всей вашей стране будут расти оливковые деревья, а маслом вы не умаститесь, потому что оливки опадут.","41":"У вас родятся сыновья и дочери, но они не останутся с вами, потому что их уведут в плен.","42":"Все ваши деревья и плоды вашей земли станут добычей вредных насекомых.","43":"Переселенцы, что живут среди вас, будут возноситься над вами все выше и выше, вы же будете опускаться все ниже и ниже.","44":"Они будут давать вам взаймы, а вы не сможете одалживать им, они будут головой, а вы – хвостом.","45":"Все эти проклятия сбудутся, они станут вас преследовать и настигнут! Вы будете уничтожены – за то, что не слушались Господа, вашего Бога, не исполняли повелений и предписаний, которые Он вам дал.","46":"Это будет знамением и знаком, явленным на вас и на потомках ваших, вовек.","47":"За то, что вы не служили Господу, вашему Богу, в радости и веселье, среди изобилия,","48":"вы будете служить врагам, которых Господь пошлет на вас, в голоде и жажде, в наготе и нужде. Враг наденет вам на шею железное ярмо – и уничтожит вас.","49":"Издалека, с края земли Господь приведет народ, который устремится на вас с быстротою орла. Это будет народ, чьего языка вы не понимаете,","50":"народ наглый, который не почитает стариков и не щадит юношей.","51":"Враги съедят ваш скот и урожай – и вы умрете. Они не оставят вам ни зерна, ни вина, ни оливкового масла, ни приплода коров, ни приплода овец и коз – и вы погибнете.","52":"Они осадят все ваши города, по всей вашей земле, – и рухнут высокие и укрепленные стены, на которые вы надеетесь. Они осадят все ваши города, по всей земле, которую отдает вам Господь, ваш Бог!","53":"В осаде, в крайностях, до которых доведут вас враги, вы будете есть детей своих, будете есть плоть тех сыновей и дочерей, что даровал вам Господь, ваш Бог.","54":"Мужчина, некогда изнеженный и избалованный, будет злобно смотреть на брата, жену и оставшихся детей,","55":"ибо он ни с кем не захочет делиться плотью детей своих, которую он поедает, не имея другой еды, в осаде, в крайностях, до которых доведут вас враги во всех ваших городах.","56":"Женщина, некогда столь изнеженная и избалованная, что даже не ступала ногой на землю, будет злобно смотреть на мужа, сына и дочь –","57":"и на послед, что выходит у нее из лона, и на младенцев, которых она рожает, ибо она будет тайком поедать их, от голода, в осаде, в крайностях, до которых доведут вас враги в ваших городах.","58":"Если вы не будете строго соблюдать и исполнять Закон, записанный в этом свитке, не будете со страхом чтить славное и страшное имя – Господа, вашего Бога, –","59":"то Господь пошлет вам и вашим потомкам небывалые несчастья, великие и непреходящие, пошлет болезни, тяжелые и продолжительные.","60":"Он снова поразит вас всеми египетскими болезнями, которых вы так боитесь, – они станут вашим уделом!","61":"Господь пошлет вам и такие болезни и несчастья, о которых не написано в этом свитке, в Законе, – и вы погибнете.","62":"Хотя вы и стали многочисленны, как звезды на небе, лишь немногие из вас уцелеют – многие погибнут за непослушание Господу, вашему Богу.","63":"Как радовался Господь, творя вам добро и делая вас многочисленным народом, так же будет Он радоваться, уничтожая и истребляя вас. Вы будете сметены с той земли, в которую вы ныне идете, чтобы овладеть ею.","64":"Господь рассеет вас среди всех народов, от края и до края земли, и там вы будете служить другим богам, которых ни вы, ни отцы ваши и не знали, – камням и деревяшкам.","65":"Среди этих народов не будет вам покоя, ноги ваши не будут знать отдыха. Там Господь заставит сердце твое трепетать, глаза – угасать, а душу – изнемогать.","66":"Твоя жизнь будет висеть на волоске, ты станешь дрожать от ужаса и днем и ночью, ты не будешь знать, останешься ли жив.","67":"Утром будешь говорить: „Скорее бы вечер!\", а вечером: „Скорее бы утро!\" – из – за страха, что овладеет тобою, из – за всего, что ты увидишь.","68":"Господь вернет вас в Египет, на кораблях, тем самым путем, про который я говорил вам, что вы никогда больше его не увидите. И там все вы, мужчины и женщины, будете предлагать себя в рабы врагам своим, но покупателя не найдется»."},"29":{"1":"Таков договор, который Господь повелел Моисею заключить с сынами Израилевыми в Моаве, – в дополнение к тому договору, что Он заключил с ними на Хориве.","2":"Моисей созвал всех сынов Израилевых и сказал: «Вы сами видели все, что сделал Господь в Египте – с фараоном, с его рабами, со всей его страной!","3":"Своими глазами видели вы эти великие и тяжкие испытания, эти великие знамения и чудеса.","4":"Но и по сей день Господь не дал вам ни разума, чтобы понять, ни глаз, чтобы видеть, ни ушей, чтобы слышать.","5":"Я сорок лет вел вас по пустыне, но одежда ваша не изнашивалась, и обувь тоже не изнашивалась.","6":"Не хлебом вы питались, не вино и пиво пили – так было, чтобы вы познали, что Я, Господь, – ваш Бог!","7":"И вот вы пришли сюда. Тогда против нас выступили Сихон, царь Хешбона, и Ог, царь Башана, но мы их разбили.","8":"Мы захватили их землю и отдали ее во владение племенам Рувима и Гада и половине племени Манассии.","9":"Соблюдайте же условия этого договора и выполняйте их – и будет вам удача во всех ваших делах!","10":"Все вы стоите ныне пред Господом, вашим Богом, – вожди, главы племен, старейшины, старосты, все сыны Израилевы,","11":"и дети, и женщины, и переселенцы, живущие среди вас, от дровосека до водоноса.","12":"Вы вступаете в скрепленный проклятиями договор с Господом, вашим Богом. Господь, ваш Бог, заключает с вами ныне этот договор,","13":"чтобы сделать вас Своим народом и стать вашим Богом – Он обещал это вам и давал такую клятву вашим прародителям Аврааму, Исааку и Иакову.","14":"Не только с вами заключаю я этот скрепленный проклятиями договор!","15":"Это договор и с теми, кто ныне стоит здесь вместе с нами пред Господом, нашим Богом, и с теми, кого нет с нами ныне.","16":"Вы помните, как мы жили в Египте, как шли потом по землям различных народов;","17":"вы видели их мерзких идолов – деревяшки и камни, изделия из серебра и золота.","18":"Да не будет такого, чтобы кто-нибудь из вас – мужчина, или женщина, или целый род, или целое племя – отвернулся ныне от Господа, нашего Бога, и пошел служить богам этих народов! Да не будет среди вас корня, рождающего яд и горечь!","19":"Пусть никто, услышав эти проклятия, не благословляет себя, мысленно говоря: „У меня все будет хорошо, хоть я и буду следовать своему упрямству\". Ведь так погибнет и орошенная земля, заодно с пересохшей!","20":"Не простит Господь такого человека: яростный гнев Господень опалит его, падут на него все проклятия, записанные в этом свитке, Господь сотрет имя его под небесами.","21":"Именно этого человека, из всех племен Израиля, Господь покарает согласно всем проклятиям договора, записанного в этом свитке, в Законе.","22":"Вот что скажет будущее поколение, ваши потомки, которые будут жить после вас, и иноплеменники, которые придут из дальних стран. Они увидят бедствия этой страны, болезни, которыми Господь поразил ее,","23":"увидят серу и соль, выжженную землю, где уже ничего не посеешь и не вырастишь, где не взойдет никакая трава, словно это Содом и Гоморра, Адма и Цевоим, города, уничтоженные Господом в гневе и ярости.","24":"Скажут все народы: „За что Господь сделал с этой страной такое? Из – за чего гнев Его разгорелся так сильно?\"","25":"Им ответят: „За то, что этот народ забыл договор с Господом, Богом их предков, который Он заключил с ними, когда вывел их из Египта.","26":"Они пошли и стали служить другим богам, стали поклоняться им – богам, которых они и не знали, которых Он им не предназначал.","27":"И разгневался Господь на эту страну и послал на нее все проклятия, записанные в этом свитке.","28":"В гневе, ярости и сильном негодовании Господь изгнал их с их земли в другую страну – они и поныне там\".","29":"Сокрытое – у Господа, нашего Бога, а открытое дано нам и детям нашим, навеки: мы должны исполнять этот Закон."},"30":{"1":"Когда сбудется все это – и благословения и проклятия, которые я предложил вам, – и вы, живя меж тех народов, среди которых рассеет вас Господь, ваш Бог, одумаетесь,","2":"и вернетесь к Господу, вашему Богу, и станете, вместе с детьми своими, слушаться Его всем сердцем и всей душой, исполняя все то, что я возвещаю вам ныне,","3":"тогда Господь, ваш Бог, вернет вам прежнее благоденствие. Он помилует вас и вновь соберет вас, уведя вас от народов, среди которых Он вас рассеял.","4":"Даже если вы будете рассеяны до края небес, и оттуда соберет вас Господь, ваш Бог, и оттуда Он вернет вас.","5":"Господь, ваш Бог, приведет вас в страну, которой владели отцы ваши, и вы снова овладеете ею. Он сотворит вам еще больше добра, чем отцам вашим, и сделает вас еще более многочисленными, чем они.","6":"Господь, ваш Бог, сделает обрезанными ваши сердца и сердца ваших потомков, чтобы вы любили Господа, вашего Бога, всем сердцем и всей душой – и остались живы.","7":"Все упомянутые проклятия Господь, ваш Бог, пошлет на ваших врагов и недругов, на тех, кто вас преследовал.","8":"Вы же снова будете слушаться Господа и исполнять все Его повеления, которые я возвещаю вам ныне.","9":"Господь, ваш Бог, даст вам все: и успех в делах, и потомство, и приплод скота, и урожай на поле – всякое благо. Господь снова будет радоваться, творя вам добро, как радовался Он об отцах ваших,","10":"ибо вы будете слушаться Господа, вашего Бога, и исполнять Его повеления и предписания, записанные в этом свитке, в Законе, и обратитесь к Господу, вашему Богу, всем сердцем и всей душой.","11":"Повеления, которые я возвещаю вам ныне, не выше вашего разумения и не слишком далеки от вас.","12":"Они не на небе, и вы не можете сказать: „Кто взойдет ради нас на небо, и принесет их, и передаст их нам, чтобы мы их исполняли?\"","13":"Они не за морем, и вы не можете сказать: „Кто отправится ради нас за море, и принесет их, и передаст их нам, чтобы мы их исполняли?\"","14":"Очень близки к вам эти повеления, они у вас на устах и в памяти вашей, и вам по силам исполнять их!","15":"Вот, я предлагаю вам ныне жизнь и благо – или же смерть и горе.","16":"Ибо ныне я повелеваю вам любить Господа, вашего Бога, ходить путями Его, исполнять Его повеления, предписания и законы – тогда вы будете живы и многочисленны, и Господь, ваш Бог, благословит вас в той стране, в которую вы идете и которой овладеете.","17":"Если же вы отвернетесь от Него, не будете Его слушаться, поддадитесь соблазну и станете поклоняться и служить другим богам,","18":"тогда – говорю вам это ныне – вы непременно погибнете! Тогда недолго будете вы жить в той стране за Иорданом, в которую вы идете и которой овладеете.","19":"Я призываю ныне в свидетели небо и землю: жизнь и смерть предложил я вам, благословение и проклятие. Выберите жизнь – и тогда вы и потомки ваши будете живы,","20":"и будете любить Господа, вашего Бога, и слушаться Его, и будете Ему верны. В Нем – ваша жизнь, долгая жизнь в той стране, которую Он поклялся отдать вашим прародителям Аврааму, Исааку и Иакову»."},"31":{"1":"Моисей пошел и возвестил все это всему народу Израиля.","2":"Моисей сказал: «Мне уже сто двадцать лет. Не по силам мне больше походы. Кроме того, Господь сказал мне: „Тебе не суждено перейти Иордан\".","3":"Господь, ваш Бог, Сам поведет вас – Он уничтожит живущие там народы, и вы овладеете их землей. Иисус поведет вас, как и велел Господь.","4":"Господь сделает с этими народами то же самое, что сделал Он с Сихоном и Огом, аморейскими царями, и с их землей (Сихона и Ога Он уничтожил).","5":"Господь дарует вам победу над этими народами, и вы поступите с ними так, как я вам повелел.","6":"Будьте твердыми и стойкими, не бойтесь и не страшитесь врагов: вместе с вами идет Господь, ваш Бог, Он не оставит и не покинет вас!»","7":"Моисей позвал Иисуса и, в присутствии всех сынов Израилевых, сказал ему: «Будь твердым и стойким. Ты поведешь этих людей в страну, которую Господь обещал отдать им – Он поклялся в этом их прародителям. Ты сделаешь эту страну их владением.","8":"Пред тобою пойдет Господь, Он будет рядом, Он не оставит и не покинет тебя. Не бойся, не страшись!»","9":"Записав этот Закон, Моисей передал его священникам, потомкам Левия, которые носят ковчег договора с Господом, и старейшинам Израиля.","10":"Он велел им: «Каждый седьмой год, в год прощения долгов, на празднике Шалашей,","11":"когда все сыны Израилевы предстанут пред Господом, вашим Богом, на том месте, которое Он изберет, читайте этот Закон вслух, чтобы слышали все сыны Израилевы.","12":"Собирайте весь народ – мужчин, женщин и детей, а также переселенцев, что живут в ваших городах, – пусть слушают и учатся: они должны бояться и чтить Господа, вашего Бога, и неукоснительно исполнять этот Закон.","13":"Пусть дети, которые еще не знают этого, тоже слушают и учатся: они должны бояться и чтить Господа, вашего Бога. Так должно быть все время, пока вы будете жить в той стране за Иорданом, в которую вы идете, чтобы овладеть ею».","14":"Господь сказал Моисею: «Близок час твоей смерти. Позови Иисуса и предстаньте предо Мною в Шатре Встречи, там Я отдам ему распоряжения». Моисей и Иисус пришли в Шатер Встречи,","15":"и Господь явился им там как столп облачный, стоящий у входа в Шатер.","16":"Господь сказал Моисею: «Скоро ты упокоишься с предками твоими. А этот народ начнет блудить с чужими богами, с богами той страны, в которую он вступает. Они оставят Меня, нарушат договор, который Я заключил с ними.","17":"Тогда Я разгневаюсь на них и тоже оставлю их; Я отвернусь от них – и они станут добычей чужаков. Многие беды и несчастья постигнут их, и тогда они скажут: „Эти беды постигли нас из – за того, что с нами нет нашего Бога!\"","18":"Я отвернусь от них за их преступление – за то, что они обратились к другим богам.","19":"Запишите же себе вот эту песнь. Научи этой песне сынов Израилевых, пусть они повторяют ее, – она будет Моей свидетельницей против них.","20":"Я приведу их на землю, которую Я с клятвой обещал их прародителям, на землю, источающую молоко и мед. Там они будут есть досыта, станут тучными, – и обратятся они к другим богам, и будут служить им! А Мною они пренебрегут, нарушат договор со Мной.","21":"И постигнут их многие беды и несчастья, и тогда эта песнь, как свидетельница, обвинит их (ведь и те поколения будут помнить ее!). Я знаю их склонности уже сейчас, еще не приведя их в страну, о которой Я клялся!»","22":"В тот же день Моисей записал эту песнь – и научил этой песне сынов Израилевых.","23":"Господь повелел Иисусу Навину: «Будь твердым и стойким. Ты поведешь сынов Израилевых в страну, которую Я поклялся отдать им. Я буду с тобой».","24":"Когда Моисей записал в свиток весь Закон, до самого конца,","25":"он велел левитам, которые носят ковчег договора с Господом:","26":"«Возьмите этот свиток, Закон, и положите его при ковчеге договора с Господом, вашим Богом; он останется там, как свидетель против вас.","27":"Ведь я знаю, что вы непокорны и упрямы! Даже сейчас, когда я еще жив, вы не слушаетесь Господа. Что же будет, когда я умру?","28":"Соберите всех старейшин племен и старост – я скажу им это и призову в свидетели против них небо и землю.","29":"Я знаю, что после моей смерти вы будете творить зло, свернете с того пути, на который я вас наставил. В грядущем вас постигнут беды, ибо вы станете совершать дела, ненавистные Господу, вызывая Его гнев творениями рук своих».","30":"И возгласил Моисей эту песнь, до конца, и ему внимала, собравшись, вся община Израиля."},"32":{"1":"«Слушай, небо, что я скажу! Земля да внимает моим словам!","2":"Польется ученье мое, словно дождь, как роса, слова мои потекут, словно дождь проливной – на траву, словно ливень – на луг!","3":"Имя Господа я призову! Славьте величие нашего Бога!","4":"Он – Скала! Совершенны Его дела, Его пути – правосудья пути. Он – Бог верный, чуждый лжи, Он праведен и справедлив.","5":"Перед Ним провинились лжедети Его. Позор им! Негодное, дурное поколенье!","6":"Как могли вы Господу так отплатить? О, тупой, неразумный народ! Ведь Он – твой Отец и Создатель твой, Основатель твой и Творец!","7":"Вспомни древние дни, времена поколений былых. Попроси – пусть расскажет отец, пусть поведают старцы тебе.","8":"Когда Вышний народам владенья давал, когда Он разделял человеческий род, народам наделы Он определил по числу Божьих сынов.","9":"Удел Господа – Его народ! Ему – Иаков принадлежит!","10":"В пустыне нашел Он этот народ, средь воющей пустоты, в глуши. Он его защищал, заботился о нем, словно зеницу ока берег.","11":"Как орел, что гнездо стережет, над птенцами своими парит, так и Он крылья простер, подхватил Свой народ и понес.","12":"В странствиях вел их Господь – один! Чужого бога не было с ними!","13":"Он им дал оседлать холмы этой земли и кормил их плодами ее полей. Из утеса медом Он их питал, маслом олив – из скалы.","14":"Сливки коровьи, козье молоко, жир ягнят, и баранов, и башанского скота, и козлов, и пшеничных колосьев тук! И вино – кровь лозы – ты пил.","15":"Растолстел Иешурун – и строптивым стал. Располнел, ожирел ты – и стал упрям. Они отвергли Бога, Творца своего, презрели спасительную Скалу!","16":"Бога в ярость приводят чужими богами – мерзостями раздражают Его!","17":"Демонам – лжебогу – приносят жертвы, богам, которых они и не знали, новым, недавно прибывшим. О них и не ведали ваши отцы!","18":"А Скалу, что тебя родила, ты забыл – Бога, что тебя произвел на свет!","19":"С омерзеньем увидел Господь, как сыновья и дочери оскорбляют Его,","20":"и сказал: „Отвернусь-ка Я от них! Посмотрю, что случится с ними! Они – испорченное поколенье, дети, забывшие долг.","21":"Лжебогом они привели Меня в ярость, раздражают идолами своими. Пошлю лженарод – пусть приводит их в ярость, пусть тупой народ раздражает их!","22":"От гнева Моего разгорелся огонь, до глубин Шеола сжигает он все! Пожирает он землю с плодами ее, основания гор сжигает!","23":"Я пошлю на них беды, одну за другой, выпущу в них все стрелы Мои!","24":"Они будут голодом истощены, измождены болезнью, лютым мором! Зубы зверей и змеиный яд – вот что Я уготовил для них.","25":"Тех, кто на улице, меч сразит, тех, кто дома остался, сразит ужас! Погибнут и юноши и девы, и младенцы и старики.","26":"Я решил было их истребить, стереть у людей даже память о них,","27":"да боюсь, Меня станут срамить их враги! Все извратят, скажут: ,Мы победили! А Господь – Он тут ни при чем' \".","28":"Ведь они – народ, лишенный ума, они ничего не в силах понять!","29":"А будь поумнее – прозрели бы, догадались бы, что их ждет.","30":"Как же один тысячу прогнал? Как же двое войско обратили в бегство? Значит, их выдала их Скала – Сам Господь их отдал врагам!","31":"Нет, „скала\" их – не то, что наша Скала! Участь наших врагов решена.","32":"Их лоза – порожденье содомской лозы и винограда садов Гоморры: ягоды – яда полны, гроздья – горьки.","33":"Их вино – это яд змеи, страшный яд гадюк!","34":"„Вот что припасено у Меня, припрятано в Моих кладовых,","35":"на день расплаты и мести, на час, когда они пошатнутся! Близок день гибели их, судьба им навстречу спешит\".","36":"Господь заступится за Свой народ, пожалеет Своих рабов – когда увидит, что сил у них нет, от мала до велика никого не осталось.","37":"Он скажет тогда: „Где же, боги их? Где, скала, на которую уповали они?","38":"Где те, что вкушали жир ваших жертв и пили вино возлияний? Пусть они теперь и спасают вас, пусть они вас и защитят!","39":"Смотрите же: это Я, Я! И рядом со Мной – никаких богов! Я убиваю – и жизнь даю, Я нанес удар – и Я исцелю. От Меня не спасет никто!","40":"К небу руку воздев, жизнью вечной Моей клянусь:","41":"когда меч Свой, молнию, Я наточу и рука Моя станет вершить суд, тогда отомщу Я врагам, недругам отплачу!","42":"Будут пьяны от крови стрелы Мои, будет Мой меч пожирать плоть. Кровь убитых и пленных! Головы вражьих вождей!\"","43":"Народы! Прославьте Его народ – за кровь рабов Своих отомстит Господь! Он отплатит Своим врагам, очистит землю народа Своего».","44":"…Моисей, придя, возгласил народу всю эту песнь, вместе с Иисусом Навином.","45":"…Возвестив все это народу Израиля,","46":"Моисей сказал: «Запомните все, что я говорю вам ныне, свидетельствуя против вас. Заповедайте своим детям строго соблюдать и исполнять этот Закон.","47":"Это не пустые слова, в них сама ваша жизнь. Благодаря им долгой будет ваша жизнь в стране за Иорданом, в которую вы идете, чтобы овладеть ею».","48":"В тот день Господь сказал Моисею:","49":"«Взойди на горы Аварим – на гору Нево, что в Моаве, напротив Иерихона, – и окинь взглядом Ханаан, страну, которую Я отдаю во владение сынам Израилевым.","50":"Ты взойдешь на эту гору и умрешь там, отойдешь к предкам, – так умер и отошел к предкам твой брат Аарон на горе Ор.","51":"Так суждено вам за то, что у источника Мериват – Кадеш, в пустыне Цин, вы согрешили предо Мной среди народа Израилева – не показали Израилю святость Мою!","52":"Ты увидишь страну, которую Я отдаю сынам Израилевым, но не войдешь в нее»."},"33":{"1":"Вот благословение, которое Моисей, человек Божий, дал перед своей смертью сыновьям Израиля.","2":"Он сказал: «Господь с Синая пришел, Он воссиял над Сеиром, явил Себя на горах Парана, пришел из Мериват – Кадеша, со склонов, с юга.","3":"Любит Он Свой народ! Все святые – в руке Твоей! Все они – у Твоих ног, исполняют веленья Твои.","4":"Моисей Наставленье нам дал, даровал его общине Иакова!","5":"И встал царь во главе Иешуруна – когда собрались вожди народа, когда племена Израиля собрались!","6":"Пусть Рувим не умирает, живет. Пусть немного людей будет в племени этом!","7":"Вот что сказал он об Иуде: „Услышь, о Господь, глас Иуды, приведи его к народу его! Он своими руками защищает себя. Помоги ему справиться с врагами!\"","8":"О Левии он сказал: „Твои туммим и урим – у того, кто верен Тебе. Ты его испытал в Массе , призвал на суд у вод Меривы .","9":"Он знать не знает отца и мать, братьев не признает, не узнает сыновей – слова Твои он хранит, соблюдает договор с Тобой.","10":"Он Иакова учит законам Твоим, Израилю возвещает Наставленье Твое, пред Тобой воскуряет жертвенный дым, возлагает всесожженье на жертвенник Твой.","11":"Благослови его мощь, Господь, дела его да будут угодны Тебе! Чресла недругов его сокруши, пусть враги его не поднимутся впредь!\"","12":"О Вениамине он сказал: „Любимец Господа живет без тревог! Господь защищает его день за днем, и на плечах Его покоится он\".","13":"Об Иосифе он сказал: „Господь его землю благословил дарами высокого неба и бездны, лежащей внизу,","14":"дарами, что солнце приносит, дарами, что луны дают,","15":"вершинами древних гор, дарами вечных холмов,","16":"дарами земли и всем, что на ней, – благоволеньем Пребывавшего в терновнике! Пусть оно главу Иосифа осенит – темя избранника средь братьев.","17":"Он – первенец Быка! Славен он! У него – рога дикого быка: он бодает ими народы, бодает все концы земли! Эти рога – сотни сотен людей Ефрема, тысячи людей Манассии!\"","18":"О Завулоне он сказал: „Радуйся, Завулон, во всех делах! Радуйся, Иссахар, в шатрах своих!","19":"Они созывают на гору племена и там приносят положенные жертвы. Их питают богатства морей, сокровища, что были сокрыты в песке!\"","20":"О Гаде он сказал: „Благословен Тот, кто Гаду обширную землю дал! Гад живет, словно лев, разрывает добычу – голову, переднюю ногу!","21":"Он избрал себе лучший надел: это – надел правителя! Когда собрались вожди народа, правосудье Господне свершил он, решенья Господа об Израиле исполнил\".","22":"О Дане он сказал: „Дан – молодой лев, что прыгает с гор Башана!\"","23":"О Неффалиме он сказал: „Неффалим, отмеченный благоволеньем, исполненный благословения Господня, владей и западом, и югом!\"","24":"Об Асире он сказал: „Асир благословен более прочих сынов! Да будет братьями он любим, пусть утопают его стопы в масле олив!","25":"Из железа и меди засовы твои. Ты всю жизнь будешь полон сил!\"","26":"… Богу Иешуруна подобных нет! Он мчится по небу на помощь тебе, по облакам – в величье Своем!","27":"Древний Бог – прибежище! Руки Вечного – опора! Он прогнал твоего врага прочь и велел: „Уничтожь его!\"","28":"Израиль живет без тревог, Иаков живет один – в стране хлеба и вина, где небо источает росу!","29":"Блажен ты, Израиль! Кто подобен тебе? О народ, чьи победы – от Господа! Он – спасающий тебя щит, Он – твоей славы меч! Пред тобою заискивать станут враги, а ты спины их будешь топтать!»"},"34":{"1":"Моисей поднялся с Моавской равнины на гору Нево – на гору Фасга, что напротив Иерихона, – и Господь показал ему всю страну: Галаад, до самого Дана,","2":"всю землю Неффалима, землю Ефрема и Манассии, всю землю Иуды, до западного моря,","3":"и Негев, и Долину (низину Иерихона, Города Пальм), до самого Цоара.","4":"И сказал Господь: «Вот страна, о которой Я клялся Аврааму, Исааку и Иакову, что отдам ее их потомкам! Я показал ее тебе, но ты не войдешь в нее».","5":"И умер Моисей, раб Господа, в Моаве, как и сказал Господь.","6":"Он был похоронен в долине, в Моаве, близ Бет – Пеора, и по сей день никому не известно, где его могила.","7":"Сто двадцать лет было Моисею, когда он умер. Зрение его не слабело и сила его не убывала – до самой смерти.","8":"Сыны Израилевы оплакивали Моисея на Моавской равнине тридцать дней – и истек срок погребального плача по Моисею.","9":"Иисус Навин был исполнен духом мудрости, ибо Моисей возложил на него руки. Слушаясь Иисуса, сыны Израилевы исполняли то, что повелел Господь через Моисея.","10":"С тех пор не было среди сынов Израилевых пророка, равного Моисею, – ведь с ним Господь говорил лицом к лицу.","11":"Какие знамения и чудеса совершил он по воле Господа в Египте – что сделал он с фараоном, с его рабами, со всей его страной!","12":"Какое могущество, какие великие и страшные дела явил Моисей на глазах у всего Израиля! Исторические книги"}};
